#include "gal_content.h"

#define GAL_CONTENT_TITLE    "爱上火车"
#define GAL_CONTENT_SUBTITLE "二六线 · 全四章"
#define GAL_CONTENT_LOGO_SUB "MAITETSU · NIIROKU"
