const gal_line_t gal_content_lines[] = {
    { "赤井", "「哪位？」", 0, GAL_UNLOCK_NONE, NULL, NULL },
    { "？？？", "「让我进去」", 0, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「哦，是二六小姐啊。请进」", 0, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「嗯……」", 0, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "二六小姐一进来就认真地观察周围，就像是归巢的小动物一样。", 1, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「真无聊。你就是有整理得太干净的习惯」", 2, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「整理得太干净的话很无聊，是吗？」", 2, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「嗯」", 3, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "二六一边说，一边熟练地将自己的电缆插进插座，然后坐下。", 3, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「赤井驾驶员，坐垫」", 4, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "……记得二六初次来访这个房间已是六个月前的事情了。", 5, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "当时她缠着我说“至少给我个坐垫吧”，所以我跟她一起出门，买下了这个可爱的坐垫。", 5, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「来，请坐」", 5, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「这个东西可以一直放着不用收拾的」", 6, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「我懂了」", 6, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "她是Ｋｕｈａ２６的专用铁路人偶，是最先进的特快电车综合管理专用的人形组件。", 6, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "帝国铁路在她娇小的身体里灌输了相当多的知识。从她刚才的低语中也能感受到这一点。", 6, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「好像确实是整理得太干净了」", 6, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「呵呵」", 7, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "只是一个坐垫就能创造容身之处。而且还能跟他人共享。", 7, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "这确实也是一种幸福。我是什么时候忘了这件事的呢？", 7, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「……」", 8, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "……二六一副心神不定的样子。她看起来有点不安。", 8, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「……我去泡茶，你稍等一下」", 8, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "我喉咙并不渴，这么做只是想让她放松一些。", 8, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「……呼」", 8, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「茶是什么味道的？」", 9, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「你没喝过吗？」", 9, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「没有。我也是第一次看到你泡茶」", 10, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「哦，是这样啊。那——」", 10, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「不用，我喝一口就好。所以直接把你那杯给我吧？」", 11, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「当然可以」", 11, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "她小心翼翼地用两只小手拿着对我来说都有点大的茶杯。", 11, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「嗯……感觉很清爽。很温暖，有股温和的味道」", 12, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「这是信徒送给我的茶叶，在隈茶中也是相当高级的货色」", 12, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「信徒？隈茶？」", 13, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「所谓“信徒”也就是——」", 13, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "虽然只是无足轻重的话题，但二六的表情却在变个不停。", 13, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「是这样啊。赤井阿苏神社、御一夜、隈元。这杯茶和赤井驾驶员的故乡——（啜一口）」", 14, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "……啊，好可爱的表情。", 14, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "让我回想起了吃饱喝足的满足感就是一种快乐。", 14, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「我想去看看。你带我去吧」", 15, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「如果电力化路段延长的话，迟早有一天能去的。隈元与御一夜之间一定会开行特快电车的」", 15, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「不是这个意思——啊！？不对。那样也行。那倒也……很棒」", 16, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "（啊）", 16, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "我或许说了不该说的话。我只是一名试车员。", 16, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "我们的交情明明只限于二六小姐——Ｋｕｈａ２６去干线正式运行前的这段短暂时光。", 16, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「……对了，二六小姐，关于下一次的试运营」", 16, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「嗯」", 17, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "二六丝毫没有掩饰自己的不快之色，很不痛快地点了点头。", 17, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "（啊）", 17, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "我暗暗告诫因此而感到欣喜的自己。", 17, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "将二六小姐转交给其他人，就是我的职责。", 17, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「你就是来向我传达这件事的吧？」", 17, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「这是我来这里的目的“之一”」", 18, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「洗耳恭听」", 18, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "我装作没注意到她的强调，催促她说下去。二六叹了口气，语气也变得严肃起来。", 18, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「从下次起，编组的车箱数将会增加。在基本的四节编组基础上，加挂ＭｏＨａＳｈｉ２１测试车」", 19, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「ＭｏＨａＳｈｉ——普通动力车厢与餐车的混用车……啊不对，是饮食柜台吗」", 19, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「对。由于Ｋｕｈａ２６编组是最快的特快列车，抵达博多时旅客们还在用餐时间。所以设有饮食柜台」", 20, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「确实。考虑到现在的电力化路段还很短，小吃吧台也属于超限设备了」", 20, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「这是对全线电力化——对于帝国铁路复活的期待和意愿的体现。我想要努力回应这样的期待」", 21, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「是啊。一起加油吧，二六小姐」", 21, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「嗯，我会加油的」", 22, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「动力车增加了，那么你的运算量也会随之增加——」", 22, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「没有问题」", 23, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "她的声音里似乎充满了自信与骄傲。", 23, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「这都在一开始的设想内。运算力绰绰有余，你就放心吧」", 24, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「是吗？但你可不能疏忽大意啊」", 24, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「我知道。安全是首要的任务」", 25, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「是啊。那么——」", 25, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「啊！」", 26, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "既然没什么问题，那么话题也就到此结束了。茶杯也空了，她充电应该也充够了。", 26, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「二六小姐，是不是差不多……？」", 26, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「不，我还有一件重要的事要说。那个，呃……」", 27, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "二六的眼神游移不定。她的视线在房间里为数不多的家具之间流连——", 27, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「对，休息日！你下一次的休息日是在……」", 28, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "（啊……）", 28, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "她的视线停在日历上。……看来她要发问了。", 28, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「那个“七”是什么？明明是二十六日却写着“七”」", 29, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「是生日」", 29, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「哎？可是，你的生日是在九月——」", 30, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「不是我的，是儿子的」", 30, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "虽说是临时驾驶员，我却对于一个刚启动半年的铁路人偶有所隐瞒。", 30, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "一想到这会对她的成长造成多恶劣的影响，我的些许感伤或许根本不值一提。", 30, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「儿子？谁的？」", 31, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「我和我前妻的」", 31, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「前妻？」", 32, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「字面意思。也就是原本的，之前的」", 32, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「前·妻——？」", 33, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「对不起」", 34, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「没事没事，幸好茶杯已经空了」", 34, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "虽然没造成任何实际损害，但二六小姐还是无比沮丧。", 34, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「我只是为了不忘记送礼物才做标记的……吓到你了？」", 34, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「嗯，我很惊讶」", 35, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「那真是失礼了」", 35, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「不会失礼。我惊讶只是因为我……嗯，我太不懂人情世故了」", 36, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「这没办法。毕竟你才刚启动半年」", 36, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「嗯」", 37, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "我的语气尽可能地放轻。", 37, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "二六小姐的声音也恢复了一点精神，看来我并没有做错。", 37, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「所以，那个……我想了解详情。因为平时没什么机会听你说这个」", 38, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「可以」", 38, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "我在放心的同时，还感到了一丝寂寞。", 38, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "驱动她的可能只是纯粹的、对于未知的好奇心。", 38, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「只要不违反保密义务，我都可以回答你。这也是我的工作」", 38, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「那我就问了」", 39, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "二六小姐的眼神中充满了光彩。她探出身体，充电线也一下子拉长，绷得紧紧的。", 39, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「那个……前·妻……也就是说你之前结过婚。而现在……是单身」", 40, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「没有错」", 40, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「孩子和那位前·妻在一起？」", 41, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「抚养权在前妻手上，而且她也讨厌我，不让我跟孩子见面」", 41, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「啊——」", 42, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "活跃起来的气氛又一下子阴沉了下去。", 42, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「二六小姐？」", 42, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「我这不懂世故的人偶可能只是在乱猜。不过你是不是……觉得很难过？」", 43, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「难过……」", 43, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "首先要小心不要被她的话给带跑。然后在这个基础上老老实实地回答。", 43, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「当初确实很难过。难过到不刻意忘记的话，就没法正常生活」", 43, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「啊！！？你也会这样？」", 44, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「嗯。因为我是个普通人嘛」", 45, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "在二六小姐的眼里，我是个很冷静沉着的人吧。", 45, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "……我只是到了不会表露出来的年纪罢了，其实我当然也会感到伤心和烦躁。", 45, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「所以我能做的只有去忘记。把一切当成是过去，只在日历上留下印记」", 45, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「生日也……」", 46, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「啊！」", 46, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "突然，我发觉到我们正在对话，喜悦之情一下子喷涌而出。", 46, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "她领会到了我的言外之意，而且还给出了回应。我都忘记这是多么令人高兴的一件事了。", 46, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「生日也得标记在日历上才能记住，你这么彻底地告别了过去吗？」", 47, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「是啊，只用五年就做到了」", 47, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「要花整整五年才能忘掉」", 48, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "她应该是在思考该怎么开口。", 48, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "二六小姐欲言又止，然后又慢慢开口道。", 48, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「你明明那么关心他们。为什么不能再相处下去呢？」", 49, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「不知道……毕竟都是陈年旧事了。那个时候的事，我已经不太能想起来了」", 49, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「但我还是想知道」", 50, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「那就说来话长了」", 50, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "二六小姐点了点头。她的眼神无比坚定。", 50, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「我想听，希望你能告诉我」", 51, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "我点了点头。然后想了一会儿该从何说起。", 51, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「……我以前也稍微提到过，我出生在神职家庭」", 51, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "别人总是说我是赤井家的孩子，神社家的孩子。在青春期前我也一直引以为傲。", 51, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「但是，到了要为未来出路而烦恼的岁数，我不禁想到一个问题。离开神社后的我，究竟还剩下些什么呢？」", 51, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「所以你成为了驾驶员？」", 52, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「我先是以此为目标。因为我喜欢铁路，所以想从事铁路相关的工作」", 52, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「嗯」", 53, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「我离开了御一夜，选择在小仓定居。参加工作是在那之后了」", 53, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "幸运的是我被聘用为洗炉工，接受考试后成为了司炉，然后又当上了司机。", 53, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "虽然很辛苦，但更多的还是快乐。因此时光也过得飞快。", 53, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「我还依次考到了动车执照和电车执照。看来我确实是很适合驾驶这一行啊」", 53, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「嗯，我认为你是天生的驾驶员。不管是对于旅客，还是对于车辆，你的驾驶都很顾及大家的感受」", 54, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「能得到你的夸奖，我很荣幸」", 54, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "不过以我的才能，大概也只能做到这么多了。", 54, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「和前妻相遇就是在那个时候——取得电车执照的不久之后」", 54, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「啊！」", 55, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「是驾驶员前辈介绍我们认识的，那位前辈说她的父亲也是铁路工人。而她也确实很理解铁路的工作」", 55, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "在休息日值班是家常便饭。就算不用值班，休息日也都是睡过去的，不然身体会支撑不住。", 55, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "因此我几乎没办法和她一起外出游玩——但她还是接受了我。", 55, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「我们顺利地在众人的祝福下结婚，并在第二年生下了孩子」", 56, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「——嗯」", 57, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「孩子出生后不久，我接到了“电车试车员”任用考试的邀请」", 57, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「好厉害，简直是飞黄腾达啊」", 58, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "二六小姐的眼神中充满了光彩。", 58, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "……在被邀请的时候，我或许也露出过这样的眼神吧。", 58, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「因为当时很少有人有电车执照。所以有执照的人基本都被邀请了吧」", 58, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「光是有执照就很厉害了。所以你立马就接受考试了？」", 59, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「是的。我立刻接受了邀请，然后每天都投入到学习和特训之中」", 59, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "我将考试合格放在了第一位，为此甚至忽视了刚出生的孩子。", 59, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "家人一定会理解我的——现在回想起来，当时我可能有过这种天真的念头。", 59, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「一开始我最大的期待是加薪。这样一来就能过上更好的生活了」", 59, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「嗯」", 60, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「但是，在重新学习帝国铁路史的时候。我的心中又萌生了其他的欲望」", 60, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「帝国铁路史——」", 61, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "很少见她这么吞吞吐吐的样子。", 61, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「我没怎么学习过」", 62, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「在明治、大正时期迅猛发展的帝国铁路的首次受挫，发生在大正三十五年」", 62, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「嗯……大正三十五年是正和元年。日本战败的那一年？」", 63, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「是的。正和元年，在化作焦土的国土上吹响复兴号角的便是铁路」", 63, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「嗯」", 64, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「然后在正和十八年，空凝机引擎实用化。正和二十一年制订并实施空凝机法」", 64, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「接下来的内容我学到过。正和三十年大幅削减了帝国铁路的相关预算」", 65, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「没错，那据说便是所谓的“大废线时代”的开始」", 65, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "大废线时代。我很讨厌这个词，甚至不想把它说出口。", 65, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「为了抵抗衰退，帝国铁路甚至不惜铤而走险」", 65, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「我知道。是干线全线电力化的构想」", 66, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「没有错。帝国铁路一边苦苦挣扎，一边为了实现这个构想而一步一步地前进」", 67, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「这件事——直接关系到了我的诞生」", 68, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「是啊，二六小姐。所以我之前一直很想见到你」", 68, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「啊！！？」", 69, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「帝国铁路的夙愿是全线电力化，以此来复兴铁路。其象征与杀手锏便是特快电车的开发」", 69, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「啊」", 70, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「我想要加入铁路复兴的计划当中。正是这股欲望让我觉得“无论如何也要成功考上”」", 70, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "此时传来了轻轻的排气声。", 70, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "听起来就像夹杂着安心和失望的叹息。", 70, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「——是这样啊。那是当然的，我也一样」", 71, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「是啊」", 71, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "只要是铁路人偶，只要是选择了将自己奉献给铁路的人皆是如此。", 71, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "但我的前妻并不这么想。而我完全没有意识到。", 71, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「在被聘用并从事这份工作后，我才后知后觉地感受到了“测试”所包含的责任」", 71, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「试车员的责任当然很重」", 72, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「是啊，没错，因为是“测试”，所以无论多么旁枝末节的数据，都必须准确采集到」", 72, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "我要做的是纯粹的机械式操作，不能带有一丝主观想法，也不能省略任何步骤。", 72, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「这是当然的。任何数据都有价值，哪怕当时还看不出其中的意义」", 73, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "二六小姐闭了闭眼睛。", 73, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "那一刻我似乎在她的眼睑上看到了沧桑的烙印，产生了一种她好像已经服役多年的错觉。", 73, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「因为有些时候，那项数据也会预知到未来将会产生的巨大危险」", 74, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「是的。从事运输行业要时刻牢记“安全是首要任务”。这点我自然是懂的」", 74, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "我在干线所感觉到的“安全”，与测试所追求的“安全”。", 74, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "哪怕目标相同，深度也完全不同。", 74, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「……测试对安全的要求有多严格，我其实并没能理解透彻」", 74, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「是吗？」", 75, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「测试车辆有时候会直接开始商业运营。但大多数情况下并非如此」", 75, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「嗯」", 76, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "若是数据表明连继续测试都有危险，那一切就都结束了。", 76, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "测试会被叫停，然后车辆……会连同铁路人偶一起被拆解。", 76, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「因为我得出的数据，今天刚组装好的铁路人偶明天便会消失」", 76, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「这是为了防患于未然。你的工作很重要，也很有价值」", 77, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「我知道。虽然我知道，但老实说，这给我带来了很大压力」", 77, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "以至于我到现在都无法摆脱这个阴影。", 77, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "哪怕只是提起这些，胃就感到一阵绞痛——", 77, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "（咕～～～～）", 77, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「啊」", 78, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「啊」", 78, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "突然。二六小姐的眼神缓和了下来。", 78, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「赤井驾驶员，你饿了？」", 79, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「不，我没觉得饿」", 79, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「但你最好吃点东西」", 80, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "二六小姐拔了插头，站起身子。", 80, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「人类只要肚子饿，情绪就会低落。姐姐们这么教过我」", 81, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "（咚咚咚咚）", 82, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「二六小姐……你会做饭啊」", 82, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「Ｄ６０ ４６姐姐跟我说“学会这个绝对能派上用场”」", 83, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「原来如此。是货运机车铁路人偶吗」", 83, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "我听说货运机车在运货时，司机经常要在不换班的情况下进行长时间、长距离的工作。", 83, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "那位铁路人偶或许学会了如何在机务段休息时，借用厨房帮司机做顿便饭。", 83, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「因为她教得很认真，所以我就都学会了。凭我的性能，做饭自然是不在话下。好，做好了」", 84, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「噢，看起来真好吃」", 84, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "萝卜味噌汤、萝卜炖鸡蛋、玉子烧配萝卜泥。", 84, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "因为冰箱里只有萝卜、味噌和鸡蛋，所以这已经是很下工夫了。", 84, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「啊，忘记煮饭了」", 85, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「啊，不必了。这些菜我拿来下酒就行」", 85, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「下酒？」", 86, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「用来敬神的酒。不过不是清酒，而是隈烧酒」", 86, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "我将在代替神龛的御神札前供奉的神酒递给她。", 86, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「这是右田一酿酒厂酿制的“右田一”。是很地道的隈烧酒」", 86, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「哦」", 87, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「在喝烧酒之前——（小口吃）嗯，好吃」", 87, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「成功了！太好了！！」", 88, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「炖萝卜也……哦，很软……嗯，嗯！真令人吃惊。味道很正，很好吃」", 88, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「毕竟老师教得好，而且我的性能也足以将学到的东西发挥出来」", 89, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「这样啊」", 89, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "大概由于她的老师是货运机车的铁路人偶吧。", 89, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "菜的口味对我来说有点偏咸，但当成下酒菜的话倒是非常合适。", 89, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「那么……」", 89, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「啊，不能自酌自饮」", 90, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「你连这种知识都学了？」", 90, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "我接过二六小姐倒好的酒，便把右田一灌入口中。", 90, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「啊啊——————好喝」", 90, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「唔，你看起来比吃我做的菜还享受」", 91, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「这是因为有你帮我斟酒啊」", 91, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「是、是吗？那……嗯，我很开心」", 92, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「那我也很开心」", 92, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "玉子烧的调味也很重，因此突显了萝卜泥的清爽。", 92, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "原来如此，确实如她所说……肚子填饱了，内心也平静了许多。", 92, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「我从来不将工作的压力带回家里」", 92, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「嗯」", 93, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "她很自然地继续听起我的述说。因此我讲起来也没了负担。", 93, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「我相信这是一种礼貌。但是……这个选择带来的只有沉默」", 93, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "若是我保持沉默，那对方也只能保持沉默。", 93, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "前妻并没有坚强到能够主动打破这种格局。或者说我们俩可能由始至终都没有真正成为夫妻。", 93, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「沉默逐渐加重，我开始不太想回家了。于是就越发投身于工作之中」", 93, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「你的工作很出色。因为你让我的诞生提早了许多！」", 94, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「如果真是这样……听到你这么说，对我来说是种莫大的宽慰」", 94, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "我心中的阴影当然还没有消失。因为我还是很对不起我的儿子。", 94, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "但是，二六小姐的话缓和了我的痛楚。", 94, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「我们的接触、交流越来越少，对方的存在越来越沉重。但是，我没能主动提出离婚」", 95, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「那就是对方提出的？」", 96, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「是的。在她提出离婚的时候我很受打击，也彻底死心。但老实说……我还松了一口气」", 96, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「你们在一起就这么难受吗？」", 97, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「……我也不知道」", 97, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "突然想喝味噌汤了。于是我又喝了一口味噌汤，而不是烧酒。", 97, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「——啊」", 97, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "一口下去，我不得不领会到另一个事实。", 97, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "那就是我已经连前妻当初每天做的味噌汤的味道都忘记了。", 97, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「我对不起前妻，但更对不起我的孩子……真希望当初我能对他投入更多的爱」", 97, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「那不可能」", 98, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「啊！！？」", 98, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「哪怕爱是无限的，时间也是有限的」", 99, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "二六笔直地注视着我。她的眼神很平静，有时会荡起一丝涟漪——就像湖面一样。", 99, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「而你的时间全部花费在了我们身上」", 100, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「——是的」", 100, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "就是这样。归根究底起来也仅仅只是如此。", 100, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "就是因为在“工作与家庭”这种老套的选择中，我总是在选择前者。", 100, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「所以，你不用再难过了」", 101, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "二六小姐看着我。她那湖面般的深邃双眸——不知怎么的让人倍感怀念。", 101, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「因为在你手中诞生的我——Ｋｕｈａ２６及其编组，是最优秀、最先进的特快电车试验列车」", 100, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「……我也是这么认为的。这是我唯一的骄傲，我对此深信不疑」", 100, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "我前妻也是成年人了，这是她自己作出的选择。我当然也一样。", 100, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "但是孩子却受到了牵连。纵使让我一辈子背负这种痛苦，我也依然有愧于他。", 100, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「因为有你我共同积累的数据，我才能这样说。这是我唯一的自信之处。」", 0, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「嗯……嗯，呵呵」", 102, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "她耀眼的笑容中充满了自信与自豪。啊……我究竟目睹过多少次这样的笑容呢？", 102, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "我究竟失去过多少个隔天就不复存在的耀眼之物呢？", 102, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「赤井驾驶员，你将时间投入在了我们身上」", 103, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "二六小姐又在看着我。她的眼神仿佛在对我说话，要我看着她的眼睛。", 103, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「我会不厌其烦地告诉你。“所以”，“我”，“才会在这里”」", 104, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「啊！」", 104, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "那双湖面般的眼睛在看着我。而湖面在荡漾。", 104, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「积累下来的数据一定会被继承下去，体现它的价值。因为铁路人偶——我们之间会进行共鸣」", 105, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "刹那间，几种神采在湖面上闪耀。那是曾经待在我身边的测试机们的眼神。", 105, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「二六小姐，你……」", 105, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「所谓最先进便是这么回事。是无数的回忆、无数的数据造就了我」", 106, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「原来……是这样啊」", 106, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "我以为自己遭到了怨恨。我甚至还想，或许被怨恨便是我的赎罪。", 106, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「所谓最先进——就是因为继承了过去的一切啊」", 106, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「我很高兴你能明白。因为你最近好像没什么精神」", 107, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「你发现了啊」", 107, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「因为我一直都很关心你」", 108, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "我看着二六小姐的双眼。她的眼中已经只剩下原来的神采了。", 108, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "意识到这是二六小姐自己所说的话，我便觉得无比欣喜。", 108, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「是吗？谢谢你」", 108, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「太好了。你没精神的原因也找到了」", 109, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「是啊」", 109, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "要说让我烦恼到连她都担心起来的原因，其实并不止这件事。", 109, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "但我并不想现在告诉她，因为这样会让她灿烂的笑容黯淡下去。", 109, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「加油吧，二六小姐。直到有一天你被称为“老车”为止」", 109, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「嗯，我很向往那个场景。我很想知道全力嫉妒那时的最先进机车是什么感觉」", 110, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「去嫉妒吧，去向往吧。到时你一定会见到让你惊讶的巨大进步」", 110, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「嗯！」", 111, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "二六小姐站了起来——啊！", 111, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「收拾的话让我来吧。也不能总是麻烦你」", 111, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「不麻烦。不过……那这样吧。两个人一起收拾，速度一定也会变成两倍」", 112, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「行啊，那就这么办吧」", 112, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「嗯！」", 113, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "……酒杯和茶杯各一个，还有味噌汤碗、盘子和小碗。", 114, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "眨眼之间收拾完后，二六小姐干脆利落地把手搭在门把上。", 114, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「和你聊了这么多，我很开心。谢谢你」", 115, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「我才要感谢你。还有，承蒙款待，真的很好吃」", 115, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「嗯……嗯，那下次我再给你做」", 116, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「嗯，下次再麻烦你了」", 116, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「我记住了，再见！」", 117, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "二六小姐走到了走廊上。我把门关好，但没有上锁。", 114, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "我觉得她可能不会喜欢那种声音——被我关在门外的声音。", 114, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "（等到脚步声消失之后再——）", 114, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「太好了！太好了！啊，四六姐！？嗯，我跟你说！特别顺利！有希望！！！」", 114, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「唔！！？」", 114, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "我禁不住想喊出声，然后又憋了回去。", 114, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「——嗯——是的——就是啊。——嗯——……煮萝卜？……教我！……还有……嗯！」", 114, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "（有希望吗）", 114, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "……二六小姐欢快的声音和脚步声越来越小，最后消失。", 114, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "（喀嚓）", 114, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「希望……啊」", 114, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "我不由地抓起自己的手腕，思考到底该如何是好。", 114, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「希望——确实是有的啊」", 114, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「嗯……」", 118, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「……什么嘛。这样根本就学不到什么。里面一辆电车也没有」", 118, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "不光是电车，就连动车和机车也没有。这本书里完全没有铁路要素。", 118, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「背景的学校既不是正和铁路也不是岩仓的学校。也不是铁路职员的职业学校」", 118, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "往后翻了几页也还是一样。肯定是四六姐哪里弄错了。", 118, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「四六姐，能听到吗？你现在在工作？」", 119, GAL_UNLOCK_NONE, NULL, NULL },
    { "四六", "「哎呀，是二六？四六没有在工作。现在在准备晚饭」", 119, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "太好了，四六姐在小仓。现在不是工作时间，共鸣不会妨碍到她。", 119, GAL_UNLOCK_NONE, NULL, NULL },
    { "四六", "「怎么了？学习又遇到问题了？」", 119, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「是啊。我不是借了少女漫画吗」", 120, GAL_UNLOCK_NONE, NULL, NULL },
    { "四六", "「哎呀，对你来说太难了？」", 120, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「倒不是难不难的问题。你要我从这本书里面学什么啊。里面又没有铁路，也没有挥旗的学生」", 121, GAL_UNLOCK_NONE, NULL, NULL },
    { "四六", "「哎呀」", 121, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "通过共鸣传来了四六姐呵呵的笑声。不明白为什么她要笑。不懂就问。", 121, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「为什么要笑？」", 122, GAL_UNLOCK_NONE, NULL, NULL },
    { "四六", "「哪有漫画能向我们铁路人偶教授铁路知识啊」", 122, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「啊，这么说也是」", 123, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "跟平时读的技术类和说明书比起来，漫画的信息量并不大。", 123, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「那……四六姐你为什么要推荐这个？」", 124, GAL_UNLOCK_NONE, NULL, NULL },
    { "四六", "「二六，你最经常找四六姐商量的问题是什么？」", 124, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「那当然是赤井驾驶员了。我想和赤井驾驶员多说说话」", 125, GAL_UNLOCK_NONE, NULL, NULL },
    { "四六", "「对吧？那四六姐给你这本漫画又想让你学些什么呢？」", 125, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「啊！我懂了。这本漫画里一定有——」", 126, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "我啪嗒一下切换了自己的思考回路，原来她不是让我学习铁路知识。", 126, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "恐怕这本漫画里有和赤井驾驶员搞好关系的秘诀！", 126, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「哇——噢噢——噢噢——嗯——嗯唔」", 126, GAL_UNLOCK_NONE, NULL, NULL },
    { "四六", "「看来你终于懂了。那你加油哦～」", 126, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「啊，嗯。谢谢四六姐。……我看看接下来的剧情——嗯——嗯——嚯——」", 126, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "好厉害，信息量好大。我一下子懂了，这漫画真的好厉害。", 126, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "书中完美描写了女生和男生怎么搞好关系。太完美了，简直是教学手册！", 126, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「而且……我好像明白了。大概是明白了」", 126, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "我终于明白了，自己想了解赤井驾驶员，想和他搞好关系的这种感情是什么。", 126, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "明白了这份感情叫什么。", 126, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「可是——」", 127, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "我不确信自己是不是对的。我可是最新型号，假如出糗了那可太难为情了。", 127, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "还是先从各个角度多收集整理一些情报，然后再征询一下其他人的意见吧。", 127, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「嗯」", 128, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "原本内心痒痒的部分发生了一些变化。那里没有消失，而是更加膨胀了。", 128, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "它膨胀起来，让我感觉不再是痒痒的，而是有些轻飘飘的。", 128, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「嗯、嗯……呜呵呵呵呵呵」", 129, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "好高兴，好幸福。弄懂了原先自己不懂的事真高兴。", 129, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "虽然我可能只是自以为懂了，要是弄错了肯定会很难堪，可这也已经让我感到很高兴了。", 129, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「恋爱——恋爱！」", 130, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "首先要确定一下这到底是不是恋爱。", 130, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "而确定的方法，肯定满满当当地塞在这本书里。", 130, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「我要重新读一遍。这次要一边读一边做笔记」", 126, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "我不能错过这本漫画里每一页、每一格内容。我要把里面人物全部的台词和行动都背下来。", 126, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "然后尽可能多次实践，做好方差分析。如果有必要的话，还要进行多重比较。", 126, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「然后就把结果告诉四六姐，征询她的意见。这样就能证实我的感情到底是不是恋爱……嗯！」", 126, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "既然定下来了，就只剩执行。没有我做不到的事。毕竟我是最新型最优秀、帝国铁路史上最高规格的铁路人偶。", 126, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「购物清单，刚出炉的吐司。在哪有卖的来着？……喂，四六姐？」", 126, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「吐司的火候，没问题。头发有没有翘起来，没问题。梳子，没问题」", 131, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "手势复诵确认。再重新确认一下步骤。", 131, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「叼着烤过的吐司用梳子梳好头发。然后在拐角和他撞上，成功再会」", 131, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "嗯，完美。可惜……只有一点在机能上无法做到。", 132, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "不，现在放弃还太早了。直到时间快到之前都应该尽可能练习。", 132, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「呼好嗯！呀次大嗯！」", 133, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "……果然不行。", 133, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "叼着吐司就没法说出“不好了！要迟到了！”。", 133, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「不过，漫画里是这么画的。一定有什么解决方法……」", 134, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「那就按照平时的方法，先立下假说然后进行验证。没关系，凭我的性能肯定马上就能解决这个矛盾」", 135, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「啊，二六小姐，早上好——哎呀，你正忙着进行演算处理吗」", 136, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「假说１６，用鼻子和上唇夹住面包。驳回假说，这样的景象在视觉上不会让人催生恋爱之情」", 137, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「……那我就不打扰你了。待会儿再见」", 138, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「假说３１，驳回。假说３２，驳回。假说３３——没时间了！赤井驾驶员要来了」", 139, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「真的来了！？啊哇哇！啊，好厉害，和漫画一模一样。不对——唔，嗯！呼好嗯！」", 140, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「呼好嗯！呀次大嗯！！」", 141, GAL_UNLOCK_NONE, NULL, NULL },
    { "？？？", "「唔哦！！？」", 132, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "（扑通！！）", 142, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「『呀！？』」", 142, GAL_UNLOCK_NONE, NULL, NULL },
    { "？？？", "「好疼——你没事呗？」", 143, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「“我、我没事”——等一下，咦，“呗”？」", 144, GAL_UNLOCK_NONE, NULL, NULL },
    { "电车段长", "「二六？你不老晒自己传感器很完美嘛，今儿咋失灵了？」", 145, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「电车段长！？为什么！？为什么是你！？」", 146, GAL_UNLOCK_NONE, NULL, NULL },
    { "电车段长", "「咋一撞上就说这些啊——嗯？为啥这儿有个烤过的吐司咧？」", 147, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「没、没、没什么！是乘务测试。那个，我先去执行乘务任务了。再见」", 148, GAL_UNLOCK_NONE, NULL, NULL },
    { "电车段长", "「要是最新型号举动古怪可是大问题——啊……咋以前也好像有一样的事儿咧……」", 149, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「……上次不算失败。因为我已经“和赤井驾驶员相遇过了”」", 150, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "既然前提条件就错了，那当然就不会得到合适的结果。仅此而已。", 150, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「现在需要的是“相遇之后提升好感度”。而最好的方式就是“投篮”」", 150, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "漫画里女主角对男主角的第一印象非常差。但却看到了他放学后在体育馆一个人进行秘密特训。", 150, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "男主角用一个难以置信的漂亮投球得分，让女主角怦然心动。", 150, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「这里就变换一下男女主的角色，我来投篮。然后让赤井驾驶员怦然心动，保证好感度上升」", 150, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "计划完美无缺，于是我做好了足够的投篮练习。", 150, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "接下来只要等到营业时间结束……３、２、１——好！", 150, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「话说，赤井驾驶员！」", 151, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「啊，二六小姐。辛苦你了」", 152, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "ＯＫ！果然他有喝和平时一样的罐装茶。我已经用一样的空罐子练好了，所以一定能成功。", 153, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「那个罐子你要扔掉吧？」", 154, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「嗯。已经喝完了」", 155, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「那给我」", 156, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「给你是可以给你——咦？」", 157, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「你看着」", 158, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "所有演算机器的起点都是弹道计算。", 159, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "而我正是最新型最高性能的铁路人偶，也具备了能够实践计算的高级身体机能——所以！", 158, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "（咻！）", 160, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「噢噢！」", 161, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "（咣！咣当……！）", 162, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「哇，真是精彩」", 163, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「还好啦——啊！！？」", 163, GAL_UNLOCK_NONE, NULL, NULL },
    { "？？？", "「哟！」", 164, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "（咻！咣当！！！）", 164, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「竟然从那么远的地方投进了！！？」", 164, GAL_UNLOCK_NONE, NULL, NULL },
    { "电车段长", "「论扔罐子咱可不输年轻人咧」", 164, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「唔——这点距离我也可以做到」", 164, GAL_UNLOCK_NONE, NULL, NULL },
    { "电车段长", "「嗯？好呀！把空罐子全拿来！」", 164, GAL_UNLOCK_NONE, NULL, NULL },
    { "技工Ａ", "「噢噢！电车段长要和二六干起来咧！？」", 164, GAL_UNLOCK_NONE, NULL, NULL },
    { "技工Ｂ", "「是传说中的扔罐子专家和最新型特快电车铁路人偶单挑啊！」", 164, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「嗯！」", 165, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "（咣当！）", 165, GAL_UNLOCK_NONE, NULL, NULL },
    { "电车段长", "「嘿呀！」", 165, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "（咣当！）", 165, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「呀！」", 165, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "（咣当！）", 165, GAL_UNLOCK_NONE, NULL, NULL },
    { "电车段长", "「嘿咻！」", 165, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "（咣当！）", 165, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「看来这场比赛会持续很久……那我就不打扰你们了」", 166, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「好缠人啊——！」", 167, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "（咣当）", 167, GAL_UNLOCK_NONE, NULL, NULL },
    { "电车段长", "「哼！」", 167, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "（咣当！）", 167, GAL_UNLOCK_NONE, NULL, NULL },
    { "技工Ａ", "「他俩都连续扔进去９个罐子咧！而且全部都是直接进筐！」", 167, GAL_UNLOCK_NONE, NULL, NULL },
    { "技工Ｂ", "「这一时半会还分不出个高低咧」", 167, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「分得出——电车段长，下一投我会关掉自己所有的传感器」", 168, GAL_UNLOCK_NONE, NULL, NULL },
    { "电车段长", "「太好咧！那咱下次遮上眼扔」", 169, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「嗯」", 170, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "我伸出手，接过罐子——是接过了吧。我把触觉和重量传感器都关了，不过没问题。", 170, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "冷静，只要完全按照刚才那９次的动作扔就行了。", 170, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "（咻——）", 170, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「咦！？」", 171, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "（咣！咚！！骨碌骨碌——）", 172, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「骗人！？没扔进去！！？」", 173, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "（咣当！！！）", 173, GAL_UNLOCK_NONE, NULL, NULL },
    { "技工Ａ", "「真不愧是传说级唉！！！」", 173, GAL_UNLOCK_NONE, NULL, NULL },
    { "技工Ｂ", "「二六就差一点，真可惜——」", 173, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「唔！！」", 174, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「啊」", 175, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "……被我扔到地上，还在滚的罐子是铁罐。刚才一直扔的却是铝罐。", 175, GAL_UNLOCK_NONE, NULL, NULL },
    { "电车段长", "「真不愧是最新型特快电车铁路人偶。把咱逼到这份儿上的你还是头一个」", 176, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「——不愧是电车段长，小仓工厂的实际最高领导人」", 177, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "电车段长的眼罩很厚，但哪怕没有摘下眼罩，他也能面向正确的方向。", 177, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "而他刚才扔的易拉罐既有铁的也有铝的。因为他只是随意接过大家交给他的易拉罐。", 177, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「概率产生了极端的偏差，而我却将这偏差错认成了正常值」", 178, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "失败的理由极其简单。而且对手是电车段长。人类是会累的。", 178, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "——身为铁路人偶，我不断重复下去总能赢过人类。可是，我却因为太想取胜而大意输掉了。", 178, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「好丢人。赤井驾驶员看到我这样子他会怎么想——！？」", 179, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「不在了！？怎么回事！？」", 180, GAL_UNLOCK_NONE, NULL, NULL },
    { "电车段长", "「唔哦！？咋了！？」", 181, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「赤井驾驶员！赤井驾驶员怎么不在？」", 182, GAL_UNLOCK_NONE, NULL, NULL },
    { "技工Ａ", "「赤井？他不在哟……」", 182, GAL_UNLOCK_NONE, NULL, NULL },
    { "技工Ｂ", "「赤井先生他打头儿就悄悄回去咧。似乎是不想妨碍你俩比试」", 182, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「回去了！？一开始就回去了！？他没看到？那——那我这么费劲有什么意义！」", 183, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "话说回来，从一半起画风就变成热血运动漫了，我明明想上演一出恋爱喜剧！", 183, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「啊啊啊啊啊啊～」", 184, GAL_UNLOCK_NONE, NULL, NULL },
    { "技工Ａ", "「啊！？她咋哭咧！？」", 184, GAL_UNLOCK_NONE, NULL, NULL },
    { "技工Ｂ", "「这是咋咧？要是出问题了咋整」", 184, GAL_UNLOCK_NONE, NULL, NULL },
    { "电车段长", "「行了」", 185, GAL_UNLOCK_NONE, NULL, NULL },
    { "技工Ａ", "「段长？」", 185, GAL_UNLOCK_NONE, NULL, NULL },
    { "电车段长", "「甭管了。小丫头这样有理由的。虽然理由让人有点儿想叹气」", 186, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「……上次失败的理由很简单。是因为“周围人太多了”」", 187, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "我可是最新型号——不，是铁路从业者，怎么能在同一件事上失败好几次呢？", 187, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「铁路是看经验的行业。而我是整个行业的结晶。没问题，按我的计划，只要等赤井驾驶员过来就好了」", 188, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "我已经查过他的日程，知道他在下班后马上会外出。而且他没拿伞就出门了。", 188, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "所以赤井驾驶员一定会经过这里。下这么大的雨也不用担心有人会在这里陪他聊天。", 188, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「台词很简单。而且讲台词的时候不用叼着面包。“没带伞吗？真拿你没办法，给”」", 189, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「哎呀，二六小姐」", 190, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「哇啊！？这就来了！！？」", 191, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「嗯？我来得太早了吗？」", 192, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「没、没有。没早，来得正好」", 193, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「来得正好？哦，是有事要找我吧」", 194, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「啊，嗯」", 195, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "现在气氛正好，我一定能说出口。就问他“没带伞吗？”。", 195, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "嗯？可是要突然这么说的话，就接不上话了。", 195, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「二六小姐？」", 196, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "得想办法铺垫一下——", 196, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「那个……天气——」", 197, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「哦，雨下得真大。回去拿伞太麻烦了」", 198, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「来了！“没带伞吗？”」", 199, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「是啊。和你一样」", 200, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「“真拿你没办法——”等等，咦？我没带伞！？？」", 201, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "没有、没有、没有。不可能，简直难以置信。自己竟然会因为太在意流程而忘记了必需的装备。", 201, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "这绝对不可能。可是不管怎么找就是找不到伞。", 201, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「是啊，真没办法。公用的伞也因为突然下雨，都被人拿走了」", 202, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「这下没办法了。我忘带伞了。连手势复诵确认都忘了」", 203, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「带伞又不是你的职务，没必要这么失落吧。没关系，我跑回宿舍去拿伞——哎呀」", 204, GAL_UNLOCK_NONE, NULL, NULL },
    { "电车段长", "「赤井，你咋在这儿呢——哦，是忘带伞了吧？哎呀，二六也在」", 205, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "怎么又是电车段长。啊——他手里拿着伞……是来补充公用的伞的啊。", 205, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「是啊，不愧是电车段长。准备就是周全」", 206, GAL_UNLOCK_NONE, NULL, NULL },
    { "电车段长", "「咱可是负责人嘛。给」", 207, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「帮大忙了，真是太感谢了」", 208, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「谢谢。可是……不。这次的失败都是我自己的责任」", 209, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「……二六小姐？你是在思考什么吗？」", 210, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「没什么，我没事。说起来赤井驾驶员，时间还来得及吗？」", 211, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「哎呀，对哦。段长，我先走了，伞先借一下了！」", 212, GAL_UNLOCK_NONE, NULL, NULL },
    { "电车段长", "「嗯——路上小心」", 213, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「一路顺风！」", 214, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「嗯，我去去就回！」", 215, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「啊！！！嗯、嗯！“一路顺风”啊。哼哼……哼哼哼」", 216, GAL_UNLOCK_NONE, NULL, NULL },
    { "电车段长", "「说句“一路顺风”和“路上小心”咋就让你这么开心咧」", 217, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「嗯。我很开心，感觉好幸福——哇！？电车段长」", 218, GAL_UNLOCK_NONE, NULL, NULL },
    { "电车段长", "「没事没事，眼不瞎的都瞅出来了。你不就是想和赤井驾驶员搞好关系呗？」", 219, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「——嗯」", 220, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "被看出来了。而且他还说，只要是不瞎的都看出来了。", 220, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "那、那——赤井驾驶员他看出来了吗？啊，等等——！", 220, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「你都看出来了为什么还要妨碍我」", 221, GAL_UNLOCK_NONE, NULL, NULL },
    { "电车段长", "「谁妨碍你咧。咱又没干啥呀？」", 222, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「刚才不也——啊，不对。刚才那件事……还有之前那几件事，都是我的失误」", 223, GAL_UNLOCK_NONE, NULL, NULL },
    { "电车段长", "「咋回事啊？」", 224, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "……我想，告诉他也没问题。毕竟我可是最新型号，肯定会被人重视的。", 224, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「嗯。我原本是有个非常棒的计划的」", 225, GAL_UNLOCK_NONE, NULL, NULL },
    { "电车段长", "「嚯？」", 226, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "我把自己的计划、行动还有实践的结果按照顺序告诉了段长。", 226, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "这些原本是想要告诉四六姐、征询她的意见的，不过多一个人能让信息准确度提高。", 226, GAL_UNLOCK_NONE, NULL, NULL },
    { "电车段长", "「……没人想妨碍你。而且你这不根本就没失败嘛」", 227, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「不会吧！？可是我——」", 228, GAL_UNLOCK_NONE, NULL, NULL },
    { "电车段长", "「甭一门儿心思都跟着漫画走。漫画里那都是极端情况咧」", 229, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「哇！」", 230, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "好厉害，不愧是电车段长——这里的最高领导人。我还是第一次这么佩服他。", 230, GAL_UNLOCK_NONE, NULL, NULL },
    { "电车段长", "「不用刻意追求感情迅速升温，每天一直待着关系也会变好的」", 231, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「真的吗！？会慢慢变好？这要怎么验证呢？」", 232, GAL_UNLOCK_NONE, NULL, NULL },
    { "电车段长", "「那就只能跟赤井本人打听咯。反正他这么老实肯定会正经回答你的呗」", 233, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「直接问他」", 234, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "我的第一反应竟然是绝对问不出口。", 234, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "我的电路不由自主地升温了，脑子里跳过了逻辑，直接蹦出了结论。", 234, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「这种话，怎么问得出口啊」", 235, GAL_UNLOCK_NONE, NULL, NULL },
    { "电车段长", "「咋的，你还害怕知道答案吗？」", 236, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「呃！！」", 237, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "怎么可能会害怕呢。不验证怎么修正结论。", 237, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "明明我的逻辑得出了这样的答案，身体却还是忍不住不停点头，就好像故障了似的。", 237, GAL_UNLOCK_NONE, NULL, NULL },
    { "电车段长", "「……既然都怕得不敢问了，那还是就老实闷着别说呗」", 238, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「啊——」", 239, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "我的确很害怕。恐怕这是身体里某个并非电路，而是更深处的位置得出的结论。", 239, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "可是——我身体深处的核心却在低语着，想要知道这个问题的答案。", 239, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「就算害怕，还是会忍不住问。这样的心情就叫做恋爱吗？」", 240, GAL_UNLOCK_NONE, NULL, NULL },
    { "电车段长", "「我们人类是这样儿的啦」", 241, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「这样啊」", 242, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "好想知道——自己现在的心情到底是不是恋爱。", 242, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "不光想要知道，而且必须知道。不然以后一定会一直后悔下去。", 242, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「……我——」", 243, GAL_UNLOCK_NONE, NULL, NULL },
    { "电车段长", "「算了，反正你慢慢儿考虑呗」", 244, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「啊」", 245, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "电车段长撑起伞，朝雨中走去。", 245, GAL_UNLOCK_NONE, NULL, NULL },
    { "电车段长", "「反正总有一天要做决定。能为这件事一直烦恼下去也算不坏咧」", 246, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「二六小姐、二六小姐。差不多该起来了」", 247, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「呼啊？」", 247, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「咦？赤井驾驶员，话说……这里是……」", 248, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「看来你真的睡得很熟。这里是御一夜温泉站，御一夜的市中心」", 249, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「啊」", 250, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "好丢人，真的睡太沉了。不过——我想想——", 250, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「我什么时候开始睡的？」", 251, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「从第四次乘车回程的时候吧。因为我说，需要的数据已经全部记录下来了」", 252, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「啊，对。然后我就一下子放松下来」", 253, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「你刚才一定是太集中精神了吧。我看你累得打哈欠，然后就马上睡着了」", 254, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「啊唔」", 255, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "好丢人。我当然是有集中精神努力收集数据没错。可是，可是，我累成这样，都是因为自己昨晚没睡好。", 255, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "因为——因为——", 255, GAL_UNLOCK_NONE, NULL, NULL },
    { "电车段长", "「派谁去视察汤医线咧——啊，那是赤井你的老家吧。咋样，你带二六去呗？」", 255, GAL_UNLOCK_NONE, NULL, NULL },
    { "四六", "「这可是机不可失的机会！就在这里一口气表白吧？？」", 255, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「啊——！？唔唔……都怪我想太多了」", 256, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「多亏了二六小姐，我们收集了足够的数据。谢谢你」", 257, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「啊！？不用这么郑重啦。这可是我的工作啊，认真工作是理所当然的」", 258, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「因为你的努力，我们完成工作之后，还有很多富余时间。接下来怎么办？要不要参观一下御一夜？」", 259, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「参观御一夜！好啊，我当然想，可是——」", 260, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「可是？」", 261, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「那……只要你不觉得我是个累赘就行——」", 262, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「你这么努力了，就当是奖励好了。你有什么愿望都可以说出来」", 263, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「愿望！」", 264, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "真好，好想试试，听着就有恋爱的感觉。", 264, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「那个，我可以说多少个愿望？」", 265, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「多少个啊……我想想，一个来回算一个愿望的话，那就三个左右？」", 266, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「那我第一个愿望，我想想，嗯——我想叫你的名字——」", 267, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「我的名字……叫我清春吗？」", 268, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「嗯、嗯。清春，清春——清春，嗯」", 269, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「单独商量工作或者现在这样的情况下都可以这么叫我，只要不是在执行工作任务的时候就行」", 270, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「那我就要叫了！现在就叫！那——那个！清——清春！」", 271, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「怎么了？二六小姐」", 272, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "好厉害，跟电车段长说的一样，跟四六姐共鸣中说的一样！", 272, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "只要一起旅行，就可以和赤井驾驶员——不，和清春瞬间拉近距离！！", 272, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「那第二个愿望！第二个！」", 273, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「第二个愿望是什么呢」", 274, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "和他拉近关系之后，自己心中的这份感情就越来越按捺不住了。", 274, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "虽然自己心中一直有着恐惧，但这份感情已经膨胀到了隐藏不住的程度。", 274, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「我希望你也不要对我用敬称。不要再叫我二六小姐了」", 275, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「当然可以。二六……这样就行了吧？」", 276, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「唔～～～～～～！！！！」", 277, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "因为这句话，我的电路简直像烧坏了一样。过热失控出错让我只能疯狂点头。", 277, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「那二六，第三个了，今天最后的愿望是什么？」", 278, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「啊！」", 279, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "清春说了。", 279, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "他说这是“今天”最后的愿望！！", 279, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「就是、就是——清春」", 280, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「我听着呢，是什么？」", 281, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「我要是以后也乖乖的，努力工作的话，等今天过了，明天、后天、今后还能向你提要求吗」", 282, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「当然可以」", 283, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「嗯！」", 284, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "那，那我就马上告诉他第三个愿望吧！", 284, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「虽然我也很想参观一下这里，不过在此之前，我想看看你家！」", 285, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「怎么样？温度有太烫或者太凉吗？」", 286, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「没有。温度正好」", 287, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「是吗」", 287, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "……总感觉有点不满。", 288, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "我明明叫了他清春，他却没有叫我二六。", 288, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「不过没想到你还帮我做了大扫除。真是太感谢你了，二六」", 289, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「不用客气！！！」", 289, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "他叫我二六了！好高兴、好高兴、好高兴、好高兴！！", 289, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「我帮忙打扫是应该的。因为你家外面那么干净里面却积满了灰尘」", 289, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「毕竟我很久不在这里住了嘛。外面会有信徒定期帮我打扫」", 289, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「都是因为你投身于试验编组，所以才好久没能回来。为了报答你，我来帮忙打扫是应该的」", 289, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「你有这份心真让我高兴——那就泡个澡好好放松一下身体吧」", 289, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「啊唔唔」", 290, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "一听清春说到身体这个词，我不知道为什么就突然害羞了起来。", 290, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "我这才重新意识到，清春跟我就隔着一堵墙，他正在给我烧柴。", 290, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「我可是让最新型号帮忙用抹布擦地板了，要是你出了什么故障，我可要被炒鱿鱼了」", 291, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「啊」", 289, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "虽然他的语气听起来像玩笑，但这是真的。", 289, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "按规矩，原本这样的视察，我是绝对不能来的。", 289, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「……对不起。都怪我说想来个大扫除」", 289, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「没有没有！我正求之不得呢。都不知道多少年没跟人比赛过抹布擦地板的速度了」", 289, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「啊」", 289, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "太好了。对，是这样的。清春刚才真的笑嘻嘻的，特别开心。", 289, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「所以我希望你好好保养自己，不要让我们之间快乐的回忆留下一个不开心的结局」", 289, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「嗯，我明白。清春」", 289, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「你理解就好。二六」", 289, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「嗯！」", 289, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "清春比任何人都要了解我。", 289, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「话说，清春！」", 289, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「在，怎么了？」", 289, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「其实，我……！」", 290, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "好想告诉他，我喜欢他。但是却说不出口。内心的恐惧一点一点涌上心头。", 292, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "（而且……清春刚才也说过）", 292, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "不要让我们之间快乐的回忆留下一个不开心的结局。", 292, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "要是现在表白失败的话，回去的旅程肯定会一片黑暗。", 292, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「噗噗噗……噗噗」", 292, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「二六？」", 293, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "可是，好想说出口，好想告诉他。因为我是那么喜欢他，喜欢到电路已经如此发烫了。", 293, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "想说、说不出口；说不出口、想说。好热，好烫——我的大脑越来越混乱了。", 293, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「噗啊！」", 294, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「二六，你怎么了？」", 294, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "清春的声音充满了担心。他在担心我。", 294, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "我好高兴，大脑都要沸腾了。整个人都红彤彤，热乎乎的——", 294, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「清、春……我——」", 294, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「二六？你泡晕了？」", 294, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "泡晕了——没错，我早就晕了。都怪清春，都怪我想更多了解他——", 294, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "（扑通！！！）", 295, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「二六！？二六！！！」", 295, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「嘿嘿……嘿嘿嘿嘿……」", 296, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "清春的手又大又暖和。", 296, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "现在的我心跳不已，感觉好像整个人飘了起来。原来两个人独处是这么幸福啊。", 296, GAL_UNLOCK_NONE, NULL, NULL },
    { "？？？", "「开啥玩笑咧！！」", 296, GAL_UNLOCK_NONE, NULL, NULL },
    { "？？？", "「电车段长人呢！找他问话！！」", 296, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「呼啊！！？」", 296, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「咦？怎么——怎么回事？清春，你在哪——这是梦！！？」", 297, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "——啊，不对。这不是。", 297, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "清春家里——赤井阿苏神社的护符还在。", 297, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「太好了，原来那不是梦啊」", 298, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "我记得我去了清春家里，泡了澡，然后我就泡晕了——", 298, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「原来泡澡泡晕就是这种情况？真是搞不懂，一会儿问问四六姐吧」", 299, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "可是，根据目前的状况，只有一种可能。那就是清春把我带了回来，让我休息。", 299, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "这衣服……一定是清春帮我穿上的。虽然穿得有点乱，但是我好高兴——不对！", 299, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「我不高兴！不对，虽然高兴，但是太可惜了！明明那是和清春多聊聊的大好机会」", 300, GAL_UNLOCK_NONE, NULL, NULL },
    { "？？？", "「咦？去赤井那儿？哦？在这之前先会合？好，知道咧」", 300, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「咦！？」", 301, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "（啪嗒啪嗒啪嗒）", 301, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "我听到了有人在大声说话，还有一阵脚步声。对了，我就是被这个吵醒的。", 301, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "说不定是发生了什么。先问问四六姐吧。", 301, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「喂，四六姐？」", 302, GAL_UNLOCK_NONE, NULL, NULL },
    { "四六", "「二六！！太好了，你醒了！」", 302, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「哎？怎么了？」", 303, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "四六姐焦急的声音马上冲进了我的脑海。", 303, GAL_UNLOCK_NONE, NULL, NULL },
    { "四六", "「一会儿再跟你解释。总之你先去最安全的地方——对，去赤井驾驶员那里！」", 303, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「怎么回事？发生什么了？？」", 304, GAL_UNLOCK_NONE, NULL, NULL },
    { "四六", "「听好了，你先去赤井先生那里。还有，会听到那边的声音的，马上切断共鸣！动作快！」", 304, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「等一下！四六姐！四六姐？？」", 305, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "共鸣突然就切断了。", 305, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "……连不上她。扩大一下频道的接收范围……啊！！！？", 305, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "（我不要被拆解！不要！好想逃！）", 306, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "（为什么会这样——明明那么努力了）", 306, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「呀！！？」", 307, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "从共鸣里传来了好多声音，充满了愤怒、悲伤和困惑，一起涌入我的脑海。", 307, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "（救命、救命、救命——救命！！！）", 307, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「不要！！！」", 308, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "我只能强行切断共鸣——然后恐怖渐渐涌上心头。", 308, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "刚才那个就是所谓的恐慌状态吧。我这才明白为什么四六姐会那么焦急。", 308, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「要是一直开着共鸣，一定会疯掉的」", 309, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "好恶心、好讨厌、好恐怖。到底发生了什么。", 309, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "不知道该如何是好——不，我明白该怎么做！", 309, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「清春」", 310, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "四六姐告诉我了。清春的身边就是最安全的地方。", 310, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「清春、清春」", 247, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "我要去。就算没有四六姐的警告，我也一定会去找他。", 247, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "无论发生什么事情，清春一定都能守护我——哪怕是这么混乱的事态。", 247, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「清——」", 247, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「二六，太好了！快过来！」", 247, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「哇！？」", 247, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "清春突然把我拉了过去——抱住了我。", 311, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "好高兴、好高兴、好高兴、好高兴！我的电路都热起来了！", 311, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「你没事吧！？太好了，我正准备去找你」", 312, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「我……没事？」", 313, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「是啊，二六你可是帝国铁路复活的象征——在这种情况下，一定会被人第一个盯上」", 314, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「盯上——」", 315, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「虽然大家平时都是好人。可是人类一旦陷入恐慌状态——」", 316, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「啊！」", 317, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "对了，恐慌。就像四六姐她们在共鸣里哭泣着叫喊着一样。", 317, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「对了！清春，到底发生了什么！？」", 318, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「啊！？你还不知道吗？」", 319, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「不知道。我只是听到了很大的声音，然后就醒了。四六姐马上在共鸣里告诉我，让我来找你」", 320, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「是这样啊——呃，我要从哪里开始解释呢」", 321, GAL_UNLOCK_NONE, NULL, NULL },
    { "？？？", "「赤井！赤井！」", 321, GAL_UNLOCK_NONE, NULL, NULL },
    { "？？？", "「赤井！你在吧！？」", 321, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「啊！你先躲在这里。听好了，一定不能出声」", 322, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「啊！！？」", 323, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "我被他塞进壁橱里藏了起来。壁橱留了一道缝隙……是不是关严实了更好？", 247, GAL_UNLOCK_NONE, NULL, NULL },
    { "？？？", "「赤井！」", 247, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「在，我这就来开门」", 247, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "进来的是我认识的人。是动车的试车员。也是清春——赤井驾驶员的前辈。", 324, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "还进来了几个技工，还有一位——可能也是驾驶员吧？", 324, GAL_UNLOCK_NONE, NULL, NULL },
    { "前辈", "「你看了这个没有！？」", 325, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「看过了。没想到他们动作这么快，而且这么极端」", 326, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "那是什么？是报纸？感觉上面好像有个大大的火车照片——", 326, GAL_UNLOCK_NONE, NULL, NULL },
    { "技工Ａ", "「“解散帝国铁路：所有线路废线·改为公路”“空凝机公交公司诞生”」", 327, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「咦！！？」", 327, GAL_UNLOCK_NONE, NULL, NULL },
    { "司机Ａ", "「咋能这么荒唐呢！？上面这是瞎想什么呢！！！」", 328, GAL_UNLOCK_NONE, NULL, NULL },
    { "技工Ｂ", "「电车段长不知跑哪去了——赤井，你知道些什么吗」", 329, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "解散帝国铁路？所有线路废线？", 329, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "——开玩笑的吧，怎么会这样——我连本线都还没上过——", 329, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「……找到电车段长之后你们想怎么做？」", 330, GAL_UNLOCK_NONE, NULL, NULL },
    { "司机Ａ", "「肯定得让他撤回这份扯淡决定啊！」", 331, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「——段长的确是小仓的最高负责人。可他也只不过是小仓的最高负责人而已啊」", 332, GAL_UNLOCK_NONE, NULL, NULL },
    { "司机Ａ", "「这！！！」", 333, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "——清春的声音十分冷静。听到他这么说，我也稍微冷静了下来。", 333, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "而且这份“决定”——假如是真的，能做到这点的也就只有——", 333, GAL_UNLOCK_NONE, NULL, NULL },
    { "前辈", "「这是政府的决定咧。又不是区区电车段长能反对的」", 334, GAL_UNLOCK_NONE, NULL, NULL },
    { "技工Ａ", "「话是这么说——」", 335, GAL_UNLOCK_NONE, NULL, NULL },
    { "司机Ａ", "「前辈，你到底是站哪边的啊！」", 336, GAL_UNLOCK_NONE, NULL, NULL },
    { "技工Ｂ", "「就算不能更改决定，也能把咱们的话传给上面呗！得让他听听咱们的意见！」", 337, GAL_UNLOCK_NONE, NULL, NULL },
    { "前辈", "「是，我就是为了商量这个，才带你们来赤井家」", 338, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "前辈带着三个人坐了下来。", 338, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "清春什么都没说，也没有给他们倒茶。", 338, GAL_UNLOCK_NONE, NULL, NULL },
    { "前辈", "「……其实我和赤井早就聊过万一出了这事怎么办咧」", 339, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「咦！！？」", 339, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「毕竟不难想象，对我们来说最糟糕的状况就是发生现在这些事。所以，当时我们思考了一下该怎么应对」", 340, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "清春这句话不是朝面前的四个人说的——是在朝我说的。", 340, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "我明白了他的用意，越发冷静了。总之先集中精力，听听他怎么说。", 340, GAL_UNLOCK_NONE, NULL, NULL },
    { "技工Ａ", "「最好的结果当然是让他们撤回解散帝国铁路的决定」", 341, GAL_UNLOCK_NONE, NULL, NULL },
    { "司机Ａ", "「就是啊！等电力化铺开，能跑电车了，那就不怕了」", 342, GAL_UNLOCK_NONE, NULL, NULL },
    { "前辈", "「那铺开的电车要赚多少才能填上偏远地区的亏损咧」", 343, GAL_UNLOCK_NONE, NULL, NULL },
    { "司机Ａ", "「这、这，就算问咱也——」", 344, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "听到前辈这么问，剩下的三个人沉默了。", 344, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "我当然是知道的。清春肯定也知道。", 344, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「……帝国铁路光去年一年亏损就有８３００亿日元以上。实际上累积债务已经有３７兆日元了」", 345, GAL_UNLOCK_NONE, NULL, NULL },
    { "技工Ｂ", "「３７兆！！？」", 346, GAL_UNLOCK_NONE, NULL, NULL },
    { "技工Ａ", "「都怪空凝机的普及——害铁路亏损呗」", 347, GAL_UNLOCK_NONE, NULL, NULL },
    { "前辈", "「不，还得是更早以前。从柴油引擎卡车成了主要物流运输工具以后就开始了」", 348, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "我知道。四六姐也抱怨过。说铁路货运的份额被卡车抢走了，帝国铁路货运也被分割出去了。", 348, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "结果这么一想，全面铺开电车的提议别说填补亏损了，完全就是反效果。", 348, GAL_UNLOCK_NONE, NULL, NULL },
    { "司机Ａ", "「从以前到现在亏了这么多……这是想还也还不上咧」", 349, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「所以我们商量过了。帝国铁路想要发展，应该民营化、分公司经营」", 350, GAL_UNLOCK_NONE, NULL, NULL },
    { "司机Ａ", "「民营化——是咋个意思？」", 351, GAL_UNLOCK_NONE, NULL, NULL },
    { "前辈", "「就是先解散帝国铁路，把它分割成几大块，再创立新的公司」", 352, GAL_UNLOCK_NONE, NULL, NULL },
    { "司机Ａ", "「什么！？」", 353, GAL_UNLOCK_NONE, NULL, NULL },
    { "技工Ａ", "「解散！」", 354, GAL_UNLOCK_NONE, NULL, NULL },
    { "技工Ｂ", "「这是让我们放弃铁路的意思呗！」", 355, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "那三个人激动得快要站起来了。好可怕，感觉他们眼睛都红了。", 355, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "可是清春却一点也不慌张。前辈也冷静地看着他们。", 355, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「资产清算后才能出售或者转让路段和车辆，只留下“需要的路段和车辆”」", 356, GAL_UNLOCK_NONE, NULL, NULL },
    { "技工Ｂ", "「啊——啊！」", 357, GAL_UNLOCK_NONE, NULL, NULL },
    { "司机Ａ", "「你是说甩掉没法赚钱的产业，只留下能赚钱的路段吗！」", 358, GAL_UNLOCK_NONE, NULL, NULL },
    { "技工Ａ", "「那太好了！这么着一弄小仓就活了！」", 359, GAL_UNLOCK_NONE, NULL, NULL },
    { "前辈", "「嗯，算是吧。当然能不能实现还不知道咧」", 360, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「……如果这件事是由帝国铁路主导，应该是很容易做到的。我本来以为，他们肯定会为了保全铁路这么做」", 361, GAL_UNLOCK_NONE, NULL, NULL },
    { "前辈", "「嗯」", 362, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "前辈没有说话。大家都紧盯着清春。", 362, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "清春表情看起来很痛苦。他露出了说出“责任”那时候的表情。", 362, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「……可是帝国铁路却没能做到。恐怕是国家或者美国不让吧」", 363, GAL_UNLOCK_NONE, NULL, NULL },
    { "技工Ａ", "「这不是能不能做到！是做不做的问题啊！！」", 364, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「啊！？」", 364, GAL_UNLOCK_NONE, NULL, NULL },
    { "司机Ａ", "「就是啊！既然帝国铁路肯定要散了，那咱们也只能干了呗！！」", 365, GAL_UNLOCK_NONE, NULL, NULL },
    { "技工Ｂ", "「赤井你肯定能行！你可是肩负帝国铁路的希望——Ｋｕｈａ２６的试车员！！」", 366, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "我无法理解。既然不知道问题的原因，自然也无法解决问题。", 366, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "可是他们为什么要这么说——", 366, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「啊」", 366, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "我明白清春为什么要把我藏起来了。恐慌原来是这么一回事。", 366, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "（陷入恐慌的人，会停止自己的思考，找个地方把愤怒发泄出来，或是抓住别人当作自己的救命稻草）", 366, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "而我正是控制Ｋｕｈａ２６的铁路人偶。也就是象征帝国铁路复活的希望本身。", 366, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "（所以才会被人第一个盯上）", 366, GAL_UNLOCK_NONE, NULL, NULL },
    { "前辈", "「赤井，咱把他们几个带过来的理由就是这个」", 367, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「……」", 368, GAL_UNLOCK_NONE, NULL, NULL },
    { "前辈", "「分割民营化必须要有个人来扛起大旗咧，不然能成的事也成不了」", 369, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「我并不适合这个职责。我没有强大到可以承担这个责任」", 369, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "责任。果然清春是这么想的，他一直为此而苦恼。", 369, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "我明白清春的想法。虽然现在情况很糟糕，我却因为这个而小小开心了一下。", 369, GAL_UNLOCK_NONE, NULL, NULL },
    { "前辈", "「我们会帮你的，你一定要扛起大旗。小仓的铁路能不能留下来就看你咧」", 369, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「不——还是请前辈接下这个职责吧。我会尽全力辅助你的」", 369, GAL_UNLOCK_NONE, NULL, NULL },
    { "前辈", "「咱要是能干早就干咧。可咱是帝工的干部，和资方那边水火不容」", 370, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "帝工是帝国铁路最大的工会。和资方一直对立——四六姐是这么对我说的。", 370, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "听说还有很多其他工会存在，工会之间也会有冲突。", 370, GAL_UNLOCK_NONE, NULL, NULL },
    { "司机Ａ", "「啊！所以才选赤井呗！不管哪个工会都和资方那边关系不好」", 371, GAL_UNLOCK_NONE, NULL, NULL },
    { "技工Ｂ", "「我们只能靠你咧」", 372, GAL_UNLOCK_NONE, NULL, NULL },
    { "技工Ａ", "「没错。求你了！」", 373, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "（嗯。现在可不是内讧的时候，这可是事关帝国铁路生死存亡的时刻）", 373, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「现在事态紧急。跟电车段长——资方那边，还有机械协会和现代劳动者工会之前的冲突就先放放吧」", 374, GAL_UNLOCK_NONE, NULL, NULL },
    { "前辈", "「不可能！他们能把事儿办这么顺利，就证明那伙人在新公司早就有地位了」", 375, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「那我们就以接受新体制为条件，让他们接受铁路的分公司经营」", 376, GAL_UNLOCK_NONE, NULL, NULL },
    { "技工Ｂ", "「这是怎么个意思——」", 377, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「在小仓内部也分区域管理。互相让步，互利共存」", 378, GAL_UNLOCK_NONE, NULL, NULL },
    { "技工Ａ", "「这……资方那边怎么可能接受咧——」", 379, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「不，就算是资方那边也会因为追求在新体制里的地位——为了拿出更好的经营成绩而接受这个条件」", 380, GAL_UNLOCK_NONE, NULL, NULL },
    { "前辈", "「……我懂了，公司要是因为解雇闹起事儿来，那帮人就很难在新公司当上管理层了呗」", 381, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "听到前辈这么说，除了清春以外的人都纷纷点头称是。", 381, GAL_UNLOCK_NONE, NULL, NULL },
    { "前辈", "「咱也琢磨不出来拿什么东西做交易。让咱去跟那帮人谈，肯定要上他们的套。只能靠你了」", 382, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「不——可是」", 383, GAL_UNLOCK_NONE, NULL, NULL },
    { "技工Ａ", "「咱都求到这份上了，你就帮帮咱们吧」", 384, GAL_UNLOCK_NONE, NULL, NULL },
    { "司机Ａ", "「赤井，难道说你已经和资方那边——」", 385, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「绝对没这回事」", 386, GAL_UNLOCK_NONE, NULL, NULL },
    { "技工Ｂ", "「那就靠你了，赤井！！」", 387, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "（这就是恐慌？这就是——“枪打出头鸟”？）", 247, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "此刻清春代替我成了那只出头鸟。", 247, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "这样是不对的，根本就反过来了嘛。因为，我只是个工具啊。", 247, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "（唰——）", 247, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「二六！？」", 388, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「清春，不用担心我。我想要帮你承担责任」", 389, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「呃！！？」", 390, GAL_UNLOCK_NONE, NULL, NULL },
    { "司机Ａ", "「啊？你是Ｋｕｈａ２６那个！？」", 391, GAL_UNLOCK_NONE, NULL, NULL },
    { "技工Ｂ", "「啊——原来藏在这儿呢」", 392, GAL_UNLOCK_NONE, NULL, NULL },
    { "技工Ａ", "「让她闭嘴！这事儿轮不到铁路人偶多嘴」", 393, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「二六。现在你先——」", 394, GAL_UNLOCK_NONE, NULL, NULL },
    { "前辈", "「不，等一下」", 395, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「二六，你退下」", 396, GAL_UNLOCK_NONE, NULL, NULL },
    { "前辈", "「我叫你等一下」", 397, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "前辈转向了我，他在笑。可我却一点也高兴不起来。", 397, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "好可怕。我觉得他的笑容好可怕。", 397, GAL_UNLOCK_NONE, NULL, NULL },
    { "前辈", "「二六啊，你打算怎么帮赤井承担责任咧？」", 398, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「那当然是让Ｋｕｈａ２６正式投入干线运营。我可是特快电车——为了不会输给空凝机才开发出来的特快电车」", 399, GAL_UNLOCK_NONE, NULL, NULL },
    { "司机Ａ", "「不会输给空凝机——对咧——你就是为了这个才开发出来的嘛」", 400, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「没错，我的运营宗旨就是要超越空凝机。我们行政特快不光速度快，乘坐起来也十分舒适」", 401, GAL_UNLOCK_NONE, NULL, NULL },
    { "技工Ａ", "「特快？……如果只论定点输送的速度，那倒是不会输给空凝机」", 402, GAL_UNLOCK_NONE, NULL, NULL },
    { "技工Ｂ", "「可空凝机能门对门运输。这咋比？」", 403, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「我们有可以坐下来慢慢享受风景、处理工作的座位和饮食柜台。能让客人在旅程中简单用餐并进行工作」", 404, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "虽然我听说空凝机是自动驾驶。只要想也可以一边移动一边工作或者吃东西。", 404, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "不过个人用空凝机无法大型化，只能以数量取胜，也没那么舒适。", 404, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「舒适就是从容不迫的态度。我们的目标用户就是这些比实惠更注重舒适的富裕阶层，靠他们来取得市场份额」", 404, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "我的目的和目标早已铭记于心，自然能够清晰传递给别人。", 404, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「只要各地的编组试验结束，可营业的线路就会增加。从帝都中央车站延至名古屋、大阪。博多那边也会连接过去」", 404, GAL_UNLOCK_NONE, NULL, NULL },
    { "技工Ｂ", "「我们的目标就是给从帝都中央车站到博多的商务旅客提供快速舒适的服务」", 404, GAL_UNLOCK_NONE, NULL, NULL },
    { "司机Ａ", "「原来如此！所以才叫行政特快啊！你——不对，上头那些做买卖的还挺会想的嘛」", 404, GAL_UNLOCK_NONE, NULL, NULL },
    { "前辈", "「原来如此。受教了」", 405, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "前辈看向清春。", 405, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "大概前辈看他的眼神和刚才看我的时候一样，十分恐怖。", 405, GAL_UNLOCK_NONE, NULL, NULL },
    { "前辈", "「赤井，铁路人偶都说到这份儿上了。要不你就应了吧」", 406, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "不过不用担心。只要是和清春在一起，无论什么困难都能克服。", 406, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "我可是最新型、最高性能的铁路人偶。是清春培养的最高杰作。", 406, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「清春，收到的署名就这些，够了吗？」", 407, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「嗯——哎呀，这可真是厉害。都超过一百了」", 408, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「这都是因为有清春的领导。而且……虽然我感觉很讨厌，但废车回送活动越来越繁忙也让人们愿意签名了」", 409, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「是啊。电车段长他们一直拒绝见面，更是让大家都不安起来了」", 410, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "自从帝国铁路解体的新闻出来后，电车段长就没和任何人见面，甚至也没见过清春。", 410, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "可他以前明明对我那么亲切——这让我感到有些不安和恐惧。", 410, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「我听说那些干部在上三层的楼梯前设了路障，是真的吗？」", 411, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「其实那不是真的路障，只是干部们轮流组成人墙，不过也跟路障差不多了」", 412, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「人墙？」", 413, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「虽然手段原始但很有效果。要是敢动他们一根手指，马上就会因为斗殴嫌疑被警察抓走，然后没收退休金」", 414, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「所以没人敢上三楼？这样就没法跟干部谈话了」", 415, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「是啊。但他们倒是还会发号施令。要是有人敢违抗也会被立即撤职」", 416, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「可是！」", 417, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "废车回送还在以每天几辆的速度进行着。而且特意从小仓运出送到门司。", 417, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "车辆拆解后就会被装上船送走，我听说门司那边的也就只剩这个工作了。", 417, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「我明白这是命令，必须服从。可是——可是四六姐她看起来好难过」", 418, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "大家都管四六姐叫死神了。", 418, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "四六姐负责牵引拉去回送的废车。因为这是最令人难过的工作，所以她就接下了。", 418, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「……二六，这就是所谓的责任。工作和生活就是这么沉重」", 419, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「可是，也有人说四六姐的司机是坏人！说他“掉头”了」", 420, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "这个词是我新学的。掉头就是转向。这是一个非常讨厌的词。意思是背叛工会，加入资方那边。", 420, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "这样做可以保证在新公司拿到工作。但也意味着舍弃迄为止的工作和铁路。", 420, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「四六姐的司机怎么会做出这种事呢！」", 421, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「别人也不知道他们内心的真实想法。所以你不要在别人面前反驳或者赞同这种言论」", 422, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「清春！？」", 423, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「有些时候就算只是插一句话都会将对方置于不利境地。这在世上是常有的事」", 424, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「所以连“不是这样！”也不能说了吗？这也是要担负的责任？」", 425, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「没错。因为你是我的铁路人偶。所以必须要承担起和我一样的责任」", 426, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「这！！！」", 427, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "刚、刚才清春他——他说了，绝对说了！！！", 427, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「我是清春的铁路人偶？」", 428, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「是的。等新公司平安创立后我也不会抛弃你。绝不会把你交给其他人」", 429, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「哇」", 430, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「如果新公司没能成功创立——那就完蛋了。就算到那时候，我也是你独一无二的驾驶员」", 431, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "虽然我明白现在不是因为这种事高兴的时候，但我还是好高兴！！！", 431, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「清春，我好高兴！不对——我的驾驶员！你是我的第一位驾驶员，也是最后一位」", 432, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「不胜荣幸，乐意之至。二六——你是我最后的铁路人偶」", 433, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「嗯！！！」", 434, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "清春刚才说我是最后的铁路人偶了！也就是说有了新公司他也绝对会一直当我的驾驶员！！", 434, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "清春会一直使用我和Ｋｕｈａ２６直到报废为止！！", 434, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「那你就告诉我，为了创立新公司，为了和你继续在铁路上行驶，我都需要做些什么」", 435, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「……这个嘛。那我们就边整理署名边谈吧」", 436, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「整理署名？」", 437, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「和我收集到的署名进行核对。按五十音顺序重新排列，去掉重复的署名，制作列表」", 438, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「我明白了」", 439, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「要是出现重复就有可能被认定为无效署名。把没填满表格的人也去掉」", 440, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「明白了。我来输入，你来检查」", 441, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「好吧。拜托你了」", 442, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「嗯」", 443, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "这种类型的工作最适合铁路人偶了。更何况我是最新型号，并行处理根本就是小菜一碟。", 247, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "清春也明白这一点。所以才说要一边工作一边谈吧。", 247, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「……一般来说，进行民营化、分公司经营对帝国铁路也是有利的」", 444, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「我也这么想。比起拆解成废铁，还是把车辆卖给想要的人更划算」", 445, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「可是这次不一样。这个政策是空凝机公司——不，是美国的命令」", 446, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「是因为清除铁路就可以加快普及空凝机了吗？」", 447, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「恐怕是吧。铁路解体后，代替它的空凝机公交公司就会成为成功转型的象征」", 448, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「那铁路想要民营化、分公司经营是很难的吗？」", 449, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "说到这里，我都怕到不敢想下去了。", 449, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "我不敢想象，姐姐、大家还有我都会连车辆一起被人拆解，化为虚无。", 449, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「二六，不用担心」", 450, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「啊——」", 451, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "清春抱住了我。", 451, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "他摸了摸我的头。我不由得停下了工作。这还怎么并行处理啊。", 451, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「既然接过了这份工作，我就要让它成功。反正我从一开始就打算这么做的」", 452, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「这样啊！」", 453, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "好高兴，我一下子就放心了。", 453, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "我这些天一点点理解了什么叫做责任，也渐渐不安了起来。", 453, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「不是因为我那个时候突然出现，才害得清春无法拒绝吗？」", 454, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「嗯——二六，你长大了，居然都会这么担心我啦」", 455, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "他摸我头的力度加大了。好舒服，心里幸福的感觉越来越强。", 455, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「我不是说过了吗，反正我早就决定了。要是失去了铁路，我过去选择的一切就都没有意义了」", 456, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「嗯」", 457, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「所以我才要先表示出不愿意的态度。表达不愿意的态度是有意义的」", 458, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「意义是什么？」", 459, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「这个啊」", 460, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「啊，等一下！」", 461, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "清春想要放开我，我不由得发出了不愿意的声音。", 461, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "……感觉好难为情。虽然难为情，但我还是要说。", 461, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「要是你不着急，就抱着我说吧。就这样抱着我，告诉我一切」", 462, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「二六，你可真是个缠人的孩子」", 463, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「……嗯」", 464, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "这次清春温柔地慢慢抚摸着我的头。", 464, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「我之所以一开始拒绝，是因为想见识一下他们的决心。我想看看会不会有人站出来」", 465, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「我懂了！要是有人站出来，就让他站在前面好了？」", 466, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「这也是一种选择。我可是很胆小的，完全不适合领着别人做事」", 467, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「我也觉得。就是因为你这么小心谨慎，才能成为最棒的试车员啊」", 468, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「你这么懂我，我就放心了」", 469, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "被清春摸着脑袋，我感到身体渐渐热了起来，有些轻飘飘的。", 469, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「可是没人站出来。也就是说他们也在一定程度上保持观望」", 470, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「——是观望要不要掉头吗？」", 471, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「说难听点就是这样。如果拿到合适条件，那四个人里谁都有掉头的可能性」", 472, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "虽然清春说这话的时候很平静，但他的声音还是透出几分落寞。这也是理所当然的。", 472, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "要是没出现这种情况，大家肯定会一直当同事。", 472, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「……嗯」", 473, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「另一个理由则是，说不定已经有人掉头去资方那边了」", 474, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "可是清春依然表现得很平常。那我也要表现得平常些。", 474, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「……那个——是不是因为，万一有资方那边的内鬼，就会把你的态度报告给他们？」", 475, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「是啊」", 476, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「——假如他们觉得你的应对很消极，可能就会试图说服你倒戈？」", 477, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「真聪明，不愧是最新型号。只启动了半年就能如此理解人类」", 478, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「才没有呢！」", 479, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "被清春称赞了，好高兴。但是我一定要表达准确的数据。", 479, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「我才没有理解人类的全部。可是——我一直在你身边，一直都看着你，所以我能理解你」", 480, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「唔！」", 481, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "清春抚摸我的手停下了。", 481, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「清春？难道我搞错了吗？？」", 482, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「啊，不是的。我只是——老实说，有点害羞」", 483, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「你也会害羞？」", 484, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「那当然是会了」", 485, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「这样啊！」", 486, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "好高兴、太高兴了。我不由得微笑了起来。我竟然让清春害羞了！", 486, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「是啊——咳咳」", 487, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "他一边继续摸着我的头，一边强行咳嗽了几声。", 487, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "清春好可爱。他这是在掩盖自己的害羞吧。", 487, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「……我们回到刚才的话题吧。能成功民营化、分公司经营当然是最理想的」", 488, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「嗯」", 489, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「可是，一旦对面判断没有交涉的余地，我们就完了。毕竟这是关乎美国的国策，不是我们这些平民能够抗衡的」", 490, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「嗯」", 491, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「我有一样绝对不能放手的东西——二六，就是你。你是我倾注了整个人生的结晶」", 492, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「——嗯」", 493, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "摸着我头的手停下来了。取而代之的是一个拥抱。", 493, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "清春用力地抱住了我。不过我却一点也不觉得难受，甚至希望他更用力些。", 493, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「就算是最坏的情况下，只要你能留下来，帝国铁路——不，铁路复活的火种就能保留下来」", 494, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「我知道。我就是这样的机体。只要有我在，Ｋｕｈａ２６的编组就能整个复原」", 495, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「我也想保下Ｋｕｈａ２６。如果可以的话，小仓到博多的线路最好也能留下来。能保下多少东西，就算多少成功」", 496, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「我明白你是怎么想的了。这份署名和你之前不配合的态度，都是为了尽可能多留下东西」", 497, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「我就是这样的人，二六。我很胆小，绝对无法成为英雄」", 498, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「嗯」", 499, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "我就是喜欢上了这样的清春。只要一想到他，心里就热热的、满满的。", 499, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "（好喜欢清春、好喜欢清春、好喜欢清春、好喜欢清春）", 499, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "现在心里的感觉和少女漫画里描写的不太一样，不是怦然心动，而是淡淡而温暖的爱。", 499, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "所以，我懂了，已经完全懂了。", 499, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「清春——我喜欢你。我一定是爱上你了」", 500, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "感觉我腹部深处的绞痛扩散了开来。", 500, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "这和漫画里的不一样，漫画里说疼的是胸口。可是我已经懂了。说出口就更明白了。", 500, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「不，不是一定。我就是爱上了你」", 501, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "我已经无法思考其他的事情了。脑海里只想着要永远陪伴他、守护他。", 501, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "喜欢、喜欢、喜欢、喜欢。我对他的爱恋已经溢于言表。", 501, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「我喜欢你。喜欢——最喜欢了」", 502, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「我……二六，我是个胆小的人」", 503, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「我知道。所以才喜欢」", 504, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「我对你的感情有爱，有执着，有欲望。可是，我已经不明白那是不是纯粹的爱情了」", 505, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「我也一样，也不知道我的喜欢是不是纯粹的啊」", 506, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「唔！」", 507, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "都是因为清春教给了我很多复杂的知识，所以我的思考才越来越冗余化了。", 507, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "有好多想让清春做的事。我也不明白这是出于欲望还是爱情了。", 507, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「但是，我喜欢你。就算这份感情不纯粹我也喜欢。就是喜欢，最喜欢了」", 508, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「就算不纯粹，就算搞不懂——」", 509, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「啊」", 510, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「你说的没错。我心里只有一件事是最清楚的」", 511, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "……骗人，这是怎么回事。明明一切发展都和少女漫画不同。", 511, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "但我明白了，绝对不会弄错，我们一定会和少女漫画走向同一个结局。", 511, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「二六，我也喜欢你」", 512, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "清春的脸越来越近了。他脸上还留着邋遢胡子，皮肤有些粗糙。", 512, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "而且，嘴唇——嘴唇！", 512, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「唔！！！」", 513, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "被他亲了。虽然只是短短碰了一下。", 513, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "这下太快了，根本没什么感觉，所以我好想再多尝试一下。", 513, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「刚刚太快了，还不知道是什么味道呢。所以，可不可以再来一次」", 514, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "清春轻轻地、温柔地笑了。", 514, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "看到他这副表情，我就知道我可以尽情向他撒娇了。", 514, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「这次再亲久一点吧？」", 515, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「这是现帝国铁路职员共计３３８人的署名。还有，这是我们主要计划的提案书」", 516, GAL_UNLOCK_NONE, NULL, NULL },
    { "电车段长", "「３３８人！你们怎么还把附近居民的签名整来了。哎呀，还没少整」", 517, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "虽然他发出惊讶的声音，但是眼神和表情却没有丝毫的动摇。", 517, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "虽然我们立场不同，互相对立，但我再一次感受到，他不愧是管理着车辆工厂和整个电车段的人物。", 517, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「我们不仅拿到了技术岗位的署名，还有行政岗位，以及干部职员的署名」", 517, GAL_UNLOCK_NONE, NULL, NULL },
    { "电车段长", "「喔……连干部职员都有」", 518, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "电车段长环视四周，好几名职员移开视线。这并不算良好的反应，我赶紧补充说道。", 518, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「这证明了，大部分人认为废除门司、小仓、博多之间的线路是非常没有意义——没有道理的一件事」", 518, GAL_UNLOCK_NONE, NULL, NULL },
    { "电车段长", "「那当然了。咱也不是傻子。小孩都能整明白的事咱能整不明白」", 519, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「嗯！？那么——可以考虑分区域管理和民营化方案吗」", 520, GAL_UNLOCK_NONE, NULL, NULL },
    { "电车段长", "「反过来说，咱能接受这种扯淡方案，肯定有咱的道理」", 521, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "电车段长看着我递给他的署名。他的嘴角忽然露出一丝笑容。", 522, GAL_UNLOCK_NONE, NULL, NULL },
    { "电车段长", "「……你整了这么多签名也不容易。那就直说了吧」", 523, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「哎？」", 523, GAL_UNLOCK_NONE, NULL, NULL },
    { "电车段长", "「二六没搁这儿吧？」", 524, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「是的。因为约定就是这样的。当然，也不仅仅是我一个人要遵守这个约定」", 524, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "我环顾四周，看到无数视线正看着我。不夸张地说，属于小仓管辖的所有驾驶员和司机都在这。", 524, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "而且他们没有任何一个人身边带着铁路人偶。因为，这就是这次面谈的条件。", 524, GAL_UNLOCK_NONE, NULL, NULL },
    { "电车段长", "「那行吧」", 525, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「啊！？您的意思是？」", 526, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "他丢给我一份文件。文件封面上用红字写着“机密”二字。", 526, GAL_UNLOCK_NONE, NULL, NULL },
    { "电车段长", "「“帝国铁路方”所有的手段都跟这儿写着呢」", 527, GAL_UNLOCK_NONE, NULL, NULL },
    { "司机Ａ", "「真的假的！？我也要看」", 528, GAL_UNLOCK_NONE, NULL, NULL },
    { "电车段长", "「后东，不准乱来！！！」", 529, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「我会念出来的！我大声念给你们听就行了吧！！」", 529, GAL_UNLOCK_NONE, NULL, NULL },
    { "后东", "「这样啊，那就拜托你了」", 530, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "人群中响起吵闹声，还有一些人想要围上来，", 530, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "而电车段长只用一声大喝就把他们镇住了。", 530, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "（……不知道这是他有意的还是无意的）", 530, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "后东庆太——在我的同期中，他是令我最不爽的人。", 530, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "虽然他很有个性，甚至被别人起了个外号叫强盗庆太……但是，或许我应该商量的人，不是前辈，而是——", 530, GAL_UNLOCK_NONE, NULL, NULL },
    { "后东", "「怎么了？该不会你碰到不认识的字了吧？」", 531, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「不，我都认识。那我念了。“关于帝国铁路解散可能遇到的反对意见与处理方法”」", 531, GAL_UNLOCK_NONE, NULL, NULL },
    { "后东", "「什么！？」", 532, GAL_UNLOCK_NONE, NULL, NULL },
    { "技工Ａ", "「所有手段？」", 533, GAL_UNLOCK_NONE, NULL, NULL },
    { "技工Ｂ", "「这是——经营方的处理方案？」", 534, GAL_UNLOCK_NONE, NULL, NULL },
    { "前辈", "「他们咋会告诉我们所有手段呢！！这是经营那边儿分化我们的策略！！！」", 535, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "前辈愤怒地喊着，人声鼎沸，场面一下子混乱了。过了好一阵子，大家才安静下来，剑拔弩张的沉默降临。", 535, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "不——这不是剑拔弩张，而是疑神疑鬼。", 535, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「……总之，我先读了。“１：铁路全部废止步骤”」", 536, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "……越是读下去，沉默就变得越是沉重。仿佛就连疑神疑鬼都要安静地被一股黑暗吞噬了一般。", 536, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "这股黑暗既冷酷又深沉浓重，其名为绝望。", 536, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "（这——这是电车段长写的吗——不，哪怕是帝国铁路高层，应该也拿不出这种东西）", 536, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "这本《运输计划书》融合了日本国内和海外视角，冷静理智到了甚至有些冷酷的地步。", 536, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "它告诉我们，一直以来，为了推广空凝机，他们正在有计划地削弱铁路的对外形象及其本身——", 536, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "（——不，这种想法太天真了。我们的对外形象会恶化，只是因为我们自身太弱了而已）", 536, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "经营不善导致员工待遇下降，待遇下降导致服务水平下降。而这又导致了进一步的经营不善，典型的恶性循环。", 536, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "当这种现象遍布全国的时候，帝国铁路就开始经常同时遭到大量批判，进一步恶化了我们的处境——", 536, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "（帝国铁路根本就没能改变——是它没有选择改变）", 536, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "哪怕从前与现在相比，经营尚算不错，职员们的士气也还不低，当时也没有选择改变。", 536, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "回头一想，那些主动选择改变的方案都被斩草除根了……这使我更感到黑暗与绝望。", 536, GAL_UNLOCK_NONE, NULL, NULL },
    { "后东", "「原来一切都只是你们的计划吗——连我们今天到这里来演了一场荒诞的闹剧也是吗！」", 537, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "后东大吼着，但是没有任何人回应他。", 537, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "“经营方”的计策实在太过周到，我实在想不出他们会给我们留下丝毫翻盘的可能性。", 537, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "（但是——即便如此，即便如此我也不能放弃二六）", 537, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「——读到这里就够了」", 538, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "我一边压制着自己的声音以免颤抖，一边看向电车段长。", 538, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "既没有同意的声音，也没有反对的声音。——没有任何人说话。", 538, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「帝国铁路——美国所谓的“解散帝国铁路”，是指要拆毁所有车辆吗？」", 538, GAL_UNLOCK_NONE, NULL, NULL },
    { "后东", "「这是什么傻话！！做这种事有什么意义？把铁路全部拆毁，改成公路，又能怎样」", 539, GAL_UNLOCK_NONE, NULL, NULL },
    { "电车段长", "「这里边可没写“全部”。也就是列举了卖掉也不碍事儿的线路而已」", 540, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "我往回翻了翻资料。要是给别人转达了错误信息就不好了。", 540, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「的确是列举了这些线路。汤医线、高森线、松浦线、三岐线。鹿儿岛干线上的川内至八代段」", 540, GAL_UNLOCK_NONE, NULL, NULL },
    { "后东", "「这不是各地都有吗！而且，这些都是非电力化的单线路段！！！」", 541, GAL_UNLOCK_NONE, NULL, NULL },
    { "电车段长", "「对。这是帝国铁路的——不对，是日本跟美国的意思」", 542, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「为了维稳——可以割让那些暂时可以保留的线路和旧型号车辆」", 542, GAL_UNLOCK_NONE, NULL, NULL },
    { "后东", "「怎么能这样！那最后一步还是废除全部铁路吗！去吃屎吧！！」", 543, GAL_UNLOCK_NONE, NULL, NULL },
    { "电车段长", "「吃屎要是能找个法子让铁路留着——那也得吃」", 544, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「啊！」", 544, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "听到这句话，我心里明白了。——一切线索都连在了一起。", 544, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "电车段长给我们看这份资料的用意，他对署名的评价，都联系在了一起。他的话语和行为，为我指明了一条线路。", 544, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「电车段长，其实你是希望铁路存续下去吧？」", 544, GAL_UNLOCK_NONE, NULL, NULL },
    { "电车段长", "「电力化线路和电车眼下是要被整没了……但那也得想法子让它们留条命啊」", 545, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「如果你有这份决心的话——电车段长，我们还可以选择利用自主运营来彻底反抗吧」", 545, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "与其苟延残喘等着被摧毁，还不如堂堂正正地应战。", 545, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「因为电车特快——行政特快它真的是，那辆在黑暗中能给我们带来光明的列车啊」", 545, GAL_UNLOCK_NONE, NULL, NULL },
    { "后东", "「带来光明——不错，行政特快“光”号配得上当我们复活用的底牌」", 546, GAL_UNLOCK_NONE, NULL, NULL },
    { "技工Ａ", "「光号」", 547, GAL_UNLOCK_NONE, NULL, NULL },
    { "技工Ｂ", "「电车特快——光号！」", 548, GAL_UNLOCK_NONE, NULL, NULL },
    { "前辈", "「你太不冷静了，赤井。与国家为敌的电车能跑几步啊」", 549, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「啊——」", 549, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "几乎快投入使用的“光”——不，活在梦幻中的“光”，会被轻易取缔。", 549, GAL_UNLOCK_NONE, NULL, NULL },
    { "电车段长", "「停止输电。撤掉架线——国家想怎么整你都行」", 550, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "……没错。大多数必要设备，都很难在绕过国家的前提下使用。", 550, GAL_UNLOCK_NONE, NULL, NULL },
    { "电车段长", "「……只能牺牲包括Ｋｕｈａ２６的所有电车还有完成电力化的线路。这么着也能让它们派上点用场」", 551, GAL_UNLOCK_NONE, NULL, NULL },
    { "前辈", "「你咋说话呢！！」", 552, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「没事，前辈。不要紧。他说的是事实，这是就事论事」", 552, GAL_UNLOCK_NONE, NULL, NULL },
    { "前辈", "「那也不能——」", 553, GAL_UNLOCK_NONE, NULL, NULL },
    { "电车段长", "「反正电车是上不了铁轨了。没法上路跑的玩意那还摆那儿当装饰吗」", 554, GAL_UNLOCK_NONE, NULL, NULL },
    { "技工Ａ", "「这——说得也是」", 555, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "原本沉默着的人们又开始慢慢议论起来。", 555, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "我再次意识到，Ｋｕｈａ２６——二六拥有着多么重大的象征意义。", 555, GAL_UNLOCK_NONE, NULL, NULL },
    { "技工Ｂ", "「那不就一点技术都继承不下来了吗——铁路这行不得靠经验吗」", 556, GAL_UNLOCK_NONE, NULL, NULL },
    { "技工Ａ", "「咋能牺牲电车技术呢！牺牲完了到时候可就找不回来了」", 557, GAL_UNLOCK_NONE, NULL, NULL },
    { "前辈", "「那咱们决裂！反抗到底！要罢工抗议也成，咱们守着架线不就得了！！」", 558, GAL_UNLOCK_NONE, NULL, NULL },
    { "后东", "「喂，怎么办，赤井」", 559, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "……后东的问题令我如坐针毡。", 559, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "我该怎么办——我能怎么办。答案只有一个，但是我实在是没有办法——", 559, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「……给我一天时间，宽限二十四小时吧」", 559, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "——我无法做出选择。那么，就只能垂死挣扎了。", 559, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "只能挣扎——抓住那点微小的希望。", 559, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「嗯」", 560, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "二六安静地点点头。与说明开始前相比，她的表情没有丝毫改变。", 560, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「清春希望怎么办，我就怎么办。能给你派上用场，就是我的幸福」", 561, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「……我认为，拯救Ｋｕｈａ２６及其编组几乎是不可能的任务」", 561, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「我也这么觉得。因为，Ｋｕｈａ２６能跑的线路已经不存在了」", 562, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "但是我很清楚。二六只不过是在故作坚强。", 562, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "她想装出平静的样子，好减少我感受到的罪恶感。", 562, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「不能在铁路上奔跑，与消失也没什么区别。如果能靠牺牲我——」", 563, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「不，二六。我不会牺牲你的」", 563, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「啊」", 564, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "我抱住她。", 564, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "我这才发现，二六的身体变得冰凉。", 564, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「二六，你是我选择的人生、是我积攒的一切凝固成的宝贵结晶，你是无可替代的」", 564, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "所以，我对她倾诉。倾诉我的热情、我的祈愿——我的心意。", 564, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「我绝对不会让步的，只有你。你是我绝对要守住的底线」", 564, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「我好高兴，清春……清春、清春」", 565, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "二六的双手回应了我的拥抱。她紧紧地抱住我。", 565, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「但是，你能做到吗？Ｋｕｈａ２６——不是会被当成废车回送吗？」", 566, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「是啊。Ｋｕｈａ２６的报废，绝对会成为小仓工厂彻底消亡的象征仪式」", 566, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「嗯」", 567, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "正因为我抱着她，才能感受她在微微颤抖。", 567, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "这让我无比想要守护。让我无比感到怜爱。", 567, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「所以，既然要通过正规手续报废，全程肯定会在严格监视之下进行」", 567, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「报废手续。是正规的」", 568, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「第一步，是检查车辆、铁路人偶驾驶体、铁路人偶整备体这三者是不是都齐全」", 568, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「嗯」", 569, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "我尽量适当地教给她工作中我不得不熟知的知识。", 569, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "那是我万般不愿告诉她的内容——但这也是为了征求她的意见。", 569, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「铁路人偶是更换操作板来测试运作是否正常的」", 569, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「测试的顺序有规定吗？」", 570, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「没有，可以随意测试。不管是从驾驶体开始，还是从整备体开始都没有关系。因为结果是一样的」", 570, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「那么，测试完之后的操作板，就放在那不动了？」", 571, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「是啊。会保持原本的状态废车回送」", 571, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「负责监视流程的人会一起上车吗？」", 572, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「不会。但是，谁都不可以停下列车。列车要直接开到进行拆解处理的门司」", 572, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「——列车到达门司之后，将会怎么样？」", 573, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「与牵引机车脱离，保留一段时间之后进行拆解。但是，严格执行正规手续的话」", 573, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「不会有保留在那里的时间」", 574, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "令人难过的是，二六得出的答案是那么正确。", 574, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「会直接进行拆解处理。不然，如果把列车暂存那里，可能会发生暗箱操作」", 575, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「没错。在那之后，门司方面将会再次测试铁路人偶的功能是否正常」", 575, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「这是——这又是为什么？测不测试不是都一样吗？」", 576, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「铁路人偶可能会自己把操作板丢到车外面。司炉，以及偷偷乘上车的人也有可能会这么做」", 576, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「啊！」", 577, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「过去就发生过类似的例子。每次发生之后，手续都会变得更严格」", 577, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「但是……电车段长如果站在我们这边，我们也可以让门司那边助我们一臂之力吧？」", 578, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「大致上来说，电车段长的确跟我们是同一边的。但是，他有一个职责必须要完成」", 578, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「必须要完成的职责？」", 579, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「那就是让尽量多的人跳槽到空凝机公交公司。这样，就可以避免太多人被炒鱿鱼」", 579, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「啊——是说他要顾忌手下的生计啦，责任之类的意思吧」", 580, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「没错。而且，虽然程度不同——前辈和其他人也是这样」", 580, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「嗯」", 581, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「要避免拥有技术、知识的人员散失。今后如果铁路还能恢复运营，他们就拥有无可估量的价值了」", 581, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「我好像能懂。要不然，到那时光是复活Ｋｕｈａ２６也没什么意义」", 582, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「这些都是为了给小仓工厂恢复电力化线路做准备。所以虽然他站在我们这边，但也不能随心所欲」", 582, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「明白了。如果贸然在门司那边找人行动，肯定会很容易走漏风声的」", 583, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「帝国铁路上层，或者更高层的人，已经派监视的人过来了吧」", 583, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「原来如此」", 584, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「等Ｋｕｈａ２６废车回送的时候，对你的监视肯定会变得更加严格」", 584, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「那么……没有漏洞可钻吗？」", 585, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「就算没有，也可以制造漏洞」", 585, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "我重新抱紧二六，说给她听的同时也是安慰着自己。", 585, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「——我想，只能放弃你的整备体了」", 585, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「嗯。打从一开始我就知道了。整备体的个体识别部位太多了」", 586, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「是啊」", 586, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "二六那冰冷的体温，苍白的脸色，比话语更清楚地表达着她的内心。", 586, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "我更用力地抱住她——好掩饰自己除此之外是多么无能为力。", 586, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「至少，我一定要保住你的驾驶体和操作板」", 586, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「嗯。我还能做自己。还能和你在一起——」", 587, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「是啊。我们要永远在一起」", 587, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「嗯」", 588, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "互相拥抱，就是互相守护。自打出生起，我头一次这么想。", 588, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "我在心里强烈地祈祷，但愿我绝不要失去怀中至爱的这份温暖。", 588, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「……对于驾驶体，有人想跟我们做个交易」", 588, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「交易？什么交易？谁想跟我们交易？」", 589, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「后东——你认识那个人吗？他是我的同期，说话很难听」", 589, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「嗯。我认识。就是那个说话很难听的——不过，他的脑子应该很好」", 590, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「是啊。这是他提出的交易」", 590, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「什么交易？」", 591, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「……现在，他的车辆和铁路人偶，正要去废车回送」", 591, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「啊！！？」", 577, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「他已经跟电车段长谈好了，他的废车回送不必经过严格手续」", 577, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "Ｋｕｈａ２６的废车回送肯定会被严格监管。", 577, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "那么在这混乱的时期中，普通车辆说不定有希望钻空子——后东赌上了这一点，而且赢了。", 577, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「不必经过严格手续，是什么意思？」", 592, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「他们省略了测试功能那一步。所以，现在他的驾驶包里，装着驾驶体的等身大模型」", 592, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「那么！后东先生的铁路人偶就可以保住驾驶体了，是吗？」", 593, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「不，二六」", 593, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "可能我不应该对她用这个说法吧。", 593, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "但是——不论用什么话语来掩饰，这都只能是一个沉重的话题。", 593, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「二六。这是为了救你。为了让交易能有个好价钱，他——」", 593, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「我明白了」", 594, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "我感受到她在我怀里点点头，看来她比我想象中坚定得多。", 594, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「后东先生的铁路人偶，为了自己的驾驶员，奉献了自己的一切，对吗」", 595, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「……是啊。对于她来说，这只是为了后东——为了她的驾驶员」", 595, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "怀中的二六又点点头，好像我说的是什么理所当然的事情一样。", 595, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "这是到底因为我和她的价值观不同呢，还是我单纯的感情用事呢——不对，这两者是一样的。", 595, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「结果就是，他保住了一台空白的驾驶体。它既没有操作板，也没有整备体、更别提车辆」", 595, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「驾驶体的个体识别部位非常少。只要拜托铁路人偶工程机械部的人动个手脚——」", 596, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「嗯，没错。明天早上，就能把她改造得跟二六一模一样」", 596, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「好厉害。果然，那个人的脑子很好」", 597, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「是啊。他这种灵活的头脑，说不定在保护铁路上能派上用场」", 597, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "电车段长、铁路人偶工程机械部部长，还有我，除了我们之外，恐怕还有好多人想拯救二六——", 597, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "他向每一个想要拯救二六的人，都做了同一个交易。", 597, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「二六。他提出的交易要求——就是让我保护你，然后在今后的某一天让电车特快复活」", 597, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「咦？说不定那个人的脑子也没有我想象中那么好」", 598, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「或许吧。即使没有任何约定，我也一定会完成这件事的」", 598, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "但是——他获得了信赖。", 598, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "他付出这些牺牲，得到了独一无二的约定——他拿来做交易的，或许并不是结果，而是过程本身吧。", 598, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「所以，接下来就是操作板了。只要能搞定操作板，接下来就好说了」", 598, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「为什么后东先生做到这种地步，也保不住操作板呢？」", 599, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「那当然是因为，我们无法保证门司那边没有上面的人渗透」", 599, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「啊，确实。不知道门司那边的人会站在哪边」", 600, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「我听说，门司那边收到命令，要把检查得到的信息报上去——不知道他们能不能做到这一步」", 600, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「我可以问问。很简单的」", 601, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「哎！？」", 601, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「因为我只要共鸣一下就行——啊，连上了！你现在还好吗？四六姐」", 602, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「这！！！」", 602, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "四六。Ｄ６０的四六。", 602, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "——那位货运机车铁路人偶独自承担了被所有人避之不及的废车回送。", 602, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「其实呢，我有事想问你。对，就是门司的事。好厉害！你怎么知道？」", 603, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "……我曾武断地认为，她这是为了在新公司站稳脚跟。", 603, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "但是——假如四六的司机愿意倾听四六的请求——", 603, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「哎？哇！四六姐，连这都帮我考虑到了！？但是这样好吗？」", 604, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "……或许，他也希望让技术传承下去，让铁路不断延续下去。", 604, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "（说不定，他还为此做了许多准备）", 604, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「嗯。我知道了。要按顺序来。我才投入运行半年多，四六姐你已经快引退了吧」", 605, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "……我的推测立刻就有了证据。二六的反应，正是基于“那个提案”。", 605, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "因为在驾驶室内，没人会想到要检查牵引机那方的铁路人偶。", 605, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「因为他是四六姐的司机啊。没有铁路人偶也能平安把车开到门司的」", 606, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "把四六的操作板放到空白的驾驶体上，然后，配以二六的整备体。", 606, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "这个手段，可以绕过一切检查。但是——却保不住四六。", 606, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「是这样吗？你的司机也要引退吗？所以，不会有任何问题？」", 607, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「……」", 607, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "怎么会呢——这根本不算是没有问题。", 607, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "但是，二六还太幼小了。她根本不能理解“死”这个词的意义。", 607, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "（但是——我也不能强行把这个概念塞给她——）", 607, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "这只会给二六带来更多的痛苦和烦恼。显而易见。", 607, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "那么，就让她保持现状——让她一无所知地经历接下来的一切才比较好吗……", 607, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「明白了。谢谢你，四六姐。嗯、嗯。我最喜欢你了！那回见！」", 608, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「呜！！！！」", 608, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「哎！！？等一下。什么事？你怎么了，清春」", 609, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「啊——没事——」", 609, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "这不是回见，而是永别。在那个瞬间来临之际，她们将不可能再见面，也不会再有共鸣——", 609, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "明明我应该告诉她这件事，但是我……我……无论如何都下不了决心。", 609, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「那个……跟四六小姐说句谢谢吧。还有，对她转达，我一定会让线路延续下去」", 609, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「我明白了！喂喂，四六姐，清春他说——嗯——嗯！我明白了！」", 610, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "二六的笑容一下子绽开。我感到怀中原本冰冷的二六再次温暖了起来。", 610, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「拜拜，四六姐，回见！嗯！」", 611, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "二六在我的怀里动了一下，抬头看我。她的眼神是那么，那么直率。", 611, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「四六姐让我转告你，“谢谢你。二六就拜托你了”」", 612, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「……是吗」", 612, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「还有，清春」", 613, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「啊」", 613, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "二六从我的怀里钻出去。她站在我的面前。再一次用直率的视线看着我。", 614, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「我的这副身体——整备体。明天是不是就要消失了？」", 615, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「是啊」", 615, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "忽然，我闻到了一种味道。——好像水的味道，又好像血的味道。", 615, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "我从未在二六身上闻到过这种味道——那是生命的味道。", 615, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「所以，我想让你再多看看我。看看我的一切——记住我的一切，一丝一毫也不要忘记」", 616, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「还有五分钟」", 617, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「嗯」", 617, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "这还是平时的房间。只有我和二六两个人。行李就在身边，已经收拾好了。", 617, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "二六的身体显得比平时还要娇小，我们像往常一样紧紧靠在一起。", 617, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「我们会顺利吧？」", 618, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「只能如此相信了」", 618, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "大家身处不同的部门，很难了解互相之间的联系，所以我选择了值得相信的人，拜托了他们。", 618, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "让他们万一失败了，马上给我发短信。", 618, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「如果没成功怎么办？」", 619, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「那只能逃跑了。没事的，船到桥头自然直」", 619, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「是这样啊」", 620, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "这大概是我第一次对二六说谎吧？", 620, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "如果我们逃跑的话，只能面对黑暗的未来。所以，我只能祈祷行动成功了。", 620, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「如果顺利逃走的话，咱们要去哪儿？」", 621, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「去哪都可以。电车段长已经帮了我们很多」", 621, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "拿到那么多职员、干部职员的署名，似乎是一项比较有用的武器。", 621, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "简直是我们把Ｋｕｈａ２６用高价卖了出去。", 621, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「公司已经决定，在帝国铁路被废除后，把许多单线、非电力化的线路与一些车辆一起出售」", 621, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「是这样啊！」", 622, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「所以，我们就去那些线路中能最快电力化的地方吧。他们一定会收留我们的」", 622, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「是这样啊，那咱们去哪里好呢？」", 623, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "二六单纯无邪地展开地图。那是再过几天之后，就会变得支离破碎的线路图。", 623, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「汤医线虽然离你家的神社很近，但是电力化应该很难吧」", 624, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "是啊。每条线路的电力化应该都很难。因为只有那种线路会被割让出去。", 624, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "或许我们的反抗本身，也早已写在他们的计划之中了。", 624, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "（线路一旦被他们截断，铁路就只有被摧毁一条路了。我必须要保护连在一起的线路）", 624, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "后东还有前辈，也不知他们将会何去何从？他们真的是我能够信赖的人吗？", 624, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "我应该跟他们一起去呢，还是应该选别的路呢。我必须仔细考虑这一点。", 624, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「我说，清春，你想去哪啊？」", 625, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「等事情结束我再慢慢想吧」", 625, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「啊！」", 626, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "时间到了。", 626, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "二六一定是很快连上了共鸣。她的身体变热了——！！？", 626, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「呀！？呀啊——啊！！这——不行！不要这样！四六姐！！」", 627, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「……」", 627, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "用语言是无法让二六理解的。我早已做好心理准备，只能让她直接面对事实。", 627, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "但即便如此，听到二六的惨叫，我的心还是被扯得粉碎。", 627, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "（——毕竟这是用蒸汽机车——Ｄ６０的量产铁路人偶的能力，来运作Ｋｕｈａ２６——最新型铁路人偶的身体）", 627, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "无论怎么想，这对四六那边的负荷都太重了。哪怕操作板瞬间损坏也不奇怪。", 627, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「不可以说话！！你会坏掉的！！四六姐！不行！你会坏掉的……」", 628, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「就算会坏掉，也只能让她继续下去」", 628, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「这！！！？」", 629, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「万一中断，四六的决心就白费了。所以，我们不能阻止她——而是要替她加油」", 629, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「呜！！！」", 630, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "最新型、最高性能。我比任何人都清楚这个词的意义。", 630, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "二六的精神明明还很幼稚，但她的计算能力却高得可悲。", 630, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「如果你做不到的话，我就作为驾驶员命令你」", 630, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「我做得到！不要命令我！我做得到——我想要做到！！！」", 631, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "所以，二六终于明白了。她明白了，无论如何，四六都会由此走向终点。", 631, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "而且万一打断她，暴露了我们动的手脚，四六一切的努力、一切的决心，就会化为泡影。", 631, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「那好，二六。尽全力为四六加油吧——」", 631, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「嗯！！！」", 632, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "驾驶体小小的身体，用力地点点头。", 632, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「加油！四六姐，加油！！！加油、加油，四六姐！！」", 633, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "（还没结束吗——）", 633, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "——验明机体。测试功能。明明这些工作应该花不了几分钟，但现在还没做完。", 633, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「加油！四六姐，不要输！！！我们和你在一起！二六和你在一起！」", 633, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "如果检查完毕的话，如果机车开始运行的话——", 633, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「啊」", 634, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "二六发出了放心的声音。信息内容是————没关系，没有发现。", 634, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「发车了吗」", 634, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「应该是的。四六姐说了一句“耶！”就睡着了」", 635, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「她——她给你发送了有意义的共鸣！？」", 635, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「虽然那边传来的信息大部分乱糟糟的，但是那句“耶！”听起来却很清楚！」", 636, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「是这样吗……货运组里，居然有人能把铁路人偶培养得这么好——」", 636, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "不由自主说出来之后，我才察觉到，不知什么时候，自己的心中已经带上了这种带有歧视的印象。", 636, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "（我还以为，货运组只会把工厂里的车辆运出去）", 636, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "但其实并非如此。他们也有属于他们自己的骄傲。", 636, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "（如果我之前和四六，以及她的司机交谈过……如果我们曾经相处过——）", 636, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "小仓各地一定有许多优秀的人，以及铁路人偶。", 636, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "如果我们互相联系，互相帮助，铺设下其它的线路——", 636, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「不……从现在开始也不晚」", 636, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「哎？什么意思？？」", 637, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「我是说，我们可以设立全新的铁路公司」", 637, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "二六纯真无邪的反应，告诉着我，四六是一位多么温柔，多么坚强的铁路人偶。", 637, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "为了缓解她的不安、她的痛苦——四六承受着不知道多沉重的负担，却还努力对她说了那句话。", 637, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「互相交谈。互相理解。帝国铁路一定已经遗忘了这件事的重要性」", 637, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "局限于把工作细分化、专业化，切断了人与人之间的联系。因领地意识而变得死板，一味守着自己的专业领域不动。", 637, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "——结果，公司对客人的服务质量不断变差，面对帝国铁路的解散，民众甚至拍手叫好。", 637, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「所以，设立全新的铁路公司之后，我想更重视沟通、理解」", 637, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「嗯！我同意！跟别人交谈真的很快乐」", 638, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「那我们就多聊聊吧。继续聊刚才的话题——建立新的铁路公司」", 638, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「嗯，其实，九州各地要电力化好像都很难。所以我很好奇，九州的外面是什么样的？」", 639, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「我也不太熟悉。你有什么想去的地方吗？」", 639, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「我想去东海道！那是日本第一的干线吧？我好想在上面跑跑看！！！」", 640, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「东海道肯定是最先被废除的线路吧——」", 640, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "……我要跟她多说说话。", 640, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "这是为了拂去二六的不安，也是为了不要让四六的愿望白费。", 640, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「那北海道怎么样？那里不是很宽广，又有很多土地吗？」", 622, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「听说那里太宽广了，下雪对铁路的影响又很厉害。电力化先不说，巡线一定非常费事吧」", 622, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「唔，那果然还是九州最好？清春，你怎么想？」", 641, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「我认为，九州其实是有潜力成为铁路王国的。所以，只要重组顺利——」", 641, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「啊！已经到达门司了！」", 642, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「唔！！！」", 642, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "共鸣恢复了——看来，四六已经解除了睡眠模式。", 642, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "看二六的反应，现在的四六状态应该比较稳定吧？", 642, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "（只要她能通过门司检查的这一关——）", 642, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "虽然我知道，心怀希望就难以保持冷静理智——虽然心里清楚，但我还是不由自主地在心里祈祷。", 642, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "他们是那么优秀的司机和铁路人偶。如果随机应变，能拿回四六的操作板——", 642, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「太好了！好像那边不需要通过检查」", 643, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「哎？」", 643, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「因为，马上又开始动了——哎？哎？？不要啊！！！？」", 644, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「快切断共鸣！！！马上！！！！」", 644, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「不要啊————————————————————————————————————————————」", 645, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「二六！！！！」", 645, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「啊啊啊啊啊啊啊啊啊啊啊啊啊啊啊啊啊啊啊啊啊啊啊啊啊啊啊啊啊啊啊啊啊啊啊啊啊啊啊啊啊啊啊啊啊啊」", 646, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "不行，二六会坏掉的！——我要切断共鸣！强行切断！！！！", 646, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「啊！！！」", 646, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「呜呜！！？——呃」", 647, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "我用大拇指，用力从正面按住二六的喉咙。驾驶体和整备体的强制关闭方式都一样。", 647, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "想要无条件停止铁路人偶的运行，这是最终的，也是唯一的强制手段。", 647, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「哈——咕——啊——呃——」", 648, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "外人看来，这姿势跟我要掐死她没什么区别。任何人都看得出这姿势不正常，第一反应就是报警。", 648, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "这个机关是为了预防有人恶意破坏铁路人偶，故意让人偶陷入假死状态，好保存数据。", 648, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「咦——呜——呜——咕」", 649, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "以保护铁路人偶的安全为最优先——为此而采取的非常手段。", 649, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "二六挣脱不开我的手，只是——在我的大拇指之下挣扎着尖叫。", 649, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「哈——呼——咕——呜嗯——」", 650, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "（快点——快点停止吧！！！）", 650, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "强制关闭需要１０秒。我以为时间已经到了的。", 650, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "明明身为驾驶员，我却失去了对时间的感知能力。", 650, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "（快点——拜托了！！！）", 650, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「啊——」", 651, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "然后——她终于无力地垂下头。手中的抵抗消失了，重量却增加了。", 651, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "我支撑着她的身体，让她横躺下——", 652, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "（啊……）", 652, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "明明我那么用力地掐了下去。可是她的脖子上，却没有丝毫的淤青。", 652, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "二六是铁路人偶。明明我早已知道了，却再度强烈地感受到这个事实。", 652, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "（时间……应该还来得及。深呼吸——总之先深呼吸一次——）", 652, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「——吸——呼！」", 652, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "……我只能想到，门司可能是在偷偷照顾我们。或者有人在那边帮我们做内鬼。", 652, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「我们的交流……沟通还不够」", 652, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "我总是在怀疑别人——只有铁路人偶们彼此信赖。", 652, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "结果，就得到了这样的下场。让二六陷入了与“死亡”的共鸣。", 652, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「应该是在一瞬间结束的。她应该……没机会再和四六共鸣了」", 652, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "对四六略去了检查，直接破坏。", 652, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "既然目的是掩人耳目，那就得尽快彻底破坏她，不留原型。", 652, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「——专用重启针呢……在哪」", 652, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "我翻找着驾驶包。", 652, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "重启开关在铁路人偶耳孔最深处。那是对于铁路人偶来说无用的孔隙。", 652, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「——二六，起床了」", 652, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "我用细细的针插入她耳朵里的插孔。", 652, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "（好）", 652, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "啪嚓一声，我感受到了扎实的回馈。", 652, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「二六？听到了吗，起床了」", 652, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「——————」", 653, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「二六？二六！起床了！！」", 653, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「——————啊」", 654, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「二六！太好了！！！二六！！二六！！」", 654, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「清——春、清春、清春」", 655, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "她已经不再混乱了。", 655, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「清春」", 656, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "而是伸出手抱住我，向我撒娇。——我的心一下子充满了喜悦！！", 656, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「二六！太好了！真是太好了！」", 656, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「清春，我坏掉了」", 657, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「是啊。但是，四六完美地——牺牲了自己，拯救了二六，还有铁路！」", 657, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「四六姐也坏掉了。我也是。我们一样。某个地方。坏掉了。再也修不好了」", 658, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「二六！！？」", 658, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "她这么说了——我才注意到。", 658, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "二六——二六的表情，从刚才开始，就没有发生任何变化。", 658, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「清春——我——在笑吗？」", 657, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「啊——嗯。你在笑哦。就像平时一样。非常可爱」", 657, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「骗人，清春。你跟刚才不一样」", 659, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「唔！！！」", 659, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "二六拿出带镜粉盒——然后安静地把它收了起来。", 659, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "（要保持自己平时的样子——）", 659, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "不能让二六继续担心下去了。想到这里，我忽然明白了四六究竟有多么坚强——", 659, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「清春？清春？你有哪里痛吗？」", 660, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「保持平时的样子——实在是——太难了」", 660, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "我的身体和话语都在颤抖。思绪也摇摆个不停。", 660, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "我完全无法压制自己由于让二六痛苦，而涌上来的罪恶感，还有后悔——", 660, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「别哭了，清春。你再哭的话，我也会，很伤心」", 661, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「对不起——对不起——二六。虽然我知道——但是——但是」", 661, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「但是，我好高兴。因为，你愿意替我哭」", 662, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「啊！」", 662, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "二六的手指无声地抚摸着我的脸颊。", 662, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "然后，她——把眼泪抹上了自己的脸颊。", 662, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「清春，你救了我。如果你没有帮我的话，我也会，彻底坏掉」", 663, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「我就知道会那样。但是——」", 663, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「所以，只要你能笑。我也会跟你一起笑的」", 664, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「唔！！！」", 664, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "我要笑。我努力翘起嘴角——垂下眼角。", 664, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「笑得好烂。清春，你根本没笑」", 659, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「那是……因为，我还，不习惯——」", 659, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「嗯，会习惯的。习惯这张脸。——还有四六姐已经不在的事实」", 665, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「是啊——我们必须习惯——习惯崭新的环境」", 665, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「嗯。但是。我希望你不要改变」", 658, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "二六的双手伸向我。我知道她在向我索求什么。", 658, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「当然不会了」", 658, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「嗯……」", 666, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "就算正在接吻的时候，二六的眼睛也没有闭上。她的脸完全僵硬了。", 666, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「我们，慢慢习惯吧。慢慢恢复吧」", 667, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「我会的。我会和你一起习惯」", 668, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「嗯」", 668, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "我完全看不出她的表情。但是，我又不可能看不出她的表情。", 668, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "刚刚，二六她是在对我微笑。", 668, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「我有点累了。可以睡一会儿吗？」", 669, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「当然可以。我把驾驶包打开」", 669, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「不要，我现在害怕驾驶包」", 670, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「是这样吗」", 670, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "我抱住她。怀中的二六用头蹭着我。", 670, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「跟你在一起，就不害怕」", 671, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「荣幸之至。那你就安心睡吧」", 671, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「嗯」", 672, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "二六放松了身上的所有力气。眼皮却一动不动。", 672, GAL_UNLOCK_NONE, NULL, NULL },
    { "赤井", "「晚安，二六」", 672, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「嗯，清春」", 673, GAL_UNLOCK_NONE, NULL, NULL },
    { "", "我用手合上她的眼皮，轻轻让她闭上眼睛。", 674, GAL_UNLOCK_NONE, NULL, NULL },
    { "二六", "「晚安」", 247, GAL_UNLOCK_NONE, NULL, NULL },
};
